export const SCRIPTING_PROMPT = "# Le langage de script de ce graphique\n\nCe document est la référence complète du moteur de script embarqué dans ce composant de graphique.\nCe n'est pas du JavaScript standard : le code s'exécute dans un bac à sable, une fois par bougie,\navec une API fixe injectée (market, chart, plot, state, bar, math, ta, strategy, alert, console)\net rien d'autre — pas de DOM, pas de réseau, pas d'import de paquet npm.\n\nRègles à respecter absolument quand tu écris un script :\n- N'utilise que les noms listés dans « Surface d'API complète » ci-dessous. Toute autre fonction n'existe pas.\n- Le script est réexécuté à chaque bougie ; garder un état d'une bougie à l'autre passe par state.*, jamais par une variable de module.\n- @indicator ou @strategy en première ligne dit ce qu'est le script. Sans l'un des deux, rien ne s'affiche.\n- Les paramètres réglables se déclarent avec new Variable(type, défaut). Ne les réaffecte jamais ailleurs.\n- Réponds toujours en français, et commente le code que tu écris.\n\n---\n\n# Surface d'API complète\n\nChaque ligne : le nom, puis sa signature et ce qu'il fait. Rien en dehors de cette liste n'existe dans le bac à sable.\n\n- `@description \"\"` — \"…\" — texte d'aide du script, affiché derrière le « ? » de l'en-tête de pane\n- `@indicator` — déclare un script qui dessine sur la chart — le cas par défaut\n- `@strategy` — déclare un script qui prend des positions — donne accès à strategy.* et ouvre le panneau de test\n- `await ai.ask(` — await ai.ask(question) — interroge le modèle configuré. @quant et @report uniquement\n- `await ai.search(` — await ai.search(requête) — interroge le modèle avec la recherche web activée\n- `await ai.json(` — await ai.json(question) — demande du JSON et le parse ; null si la réponse n'en est pas\n- `@report` — déclare un script qui écrit un document — report.* au lieu de plot.*, exportable en PDF\n- `@quant(` — déclare une analyse qui ne dessine rien — une exécution par symbole, le résultat est ce que le script renvoie\n- `strategy` — long/short/close + position/positionSize/averagePrice/unrealizedProfit — scripts @strategy uniquement\n- `strategy.long` — (commentaire?, { size?, unit? }?) — ouvre ou renforce une position longue\n- `strategy.short` — (commentaire?, { size?, unit? }?) — ouvre ou renforce une position courte\n- `strategy.close` — (commentaire?) — ferme toute la position ouverte\n- `strategy.position` — () => \"long\" | \"short\" | \"flat\"\n- `strategy.positionSize` — () => number — unités détenues\n- `strategy.averagePrice` — () => number | null — prix moyen d'entrée\n- `strategy.unrealizedProfit` — () => number — P&L latent au cours courant\n- `@block ` — titre — ouvre une cellule ; Maj+Entrée exécute du début du script jusqu'à la fin de celle du curseur. @block(id at x y after autre) porte en plus la position et les dépendances du bloc en mode no-code.\n- `new Variable(\"number\", 1, { description: \"\" })` — (type, défaut, { description?, min?, max? }) — paramètre réglable : \"string\" | \"number\" | \"boolean\" | \"Array[string]\" | \"Array[number]\" | \"color\". min/max uniquement pour \"number\".\n- `const DEBOUNCE_MS = new Variable(\"number\", 300, { min: 0 });` — const DEBOUNCE_MS = new Variable(\"number\", 300) — délai (ms) d'anti-rafale avant un recalcul déclenché par un tick de marché en direct sur la bougie en formation. 0 = aucun anti-rafale. Sans effet sur le replay ou une nouvelle bougie. Défaut 300 si non déclaré.\n- `market.open()` — (offset?) => number | null\n- `market.high()` — (offset?) => number | null\n- `market.low()` — (offset?) => number | null\n- `market.close()` — (offset?) => number | null\n- `market.volume()` — (offset?) => number | null\n- `market.time()` — (offset?) => Date | null\n- `market.series(\"close\", 20)` — (\"open\"|\"high\"|\"low\"|\"close\"|\"volume\", count?) => number[]\n- `market.heikinAshi(200)` — (count?) => {open,high,low,close} — séries Heikin-Ashi, plus ancienne d'abord\n- `market.availableTimeframes()` — () => string[]\n- `market.resample(\"1h\")` — (\"5m\"|\"15m\"|\"1h\"|\"4h\"|\"1d\"|...) => handle for another timeframe\n- `company.value(\"eps\")` — (champ, offset?) => number | null — ce que la société a publié, à la bougie courante\n- `company.fields()` — () => string[] — les métriques disponibles sur ce graphe\n- `chart.indicator(\"rsi\")` — (id) => handle — see chart.listIndicators()\n- `chart.listIndicators()` — () => string[]\n- `.value` — (offset?) => number | null — plain/band indicators\n- `.line` — (offset?) => number | null — MACD  ·  (name, value, options?) — pane.line/overlay.line\n- `.signal` — (offset?) => number | null — MACD\n- `.histogram` — (offset?) => number | null — MACD  ·  (name, value, options?) — pane.histogram/overlay.histogram\n- `profile(\"Densité\", valeurs, prix)` — (nom, valeurs, prix, options?) — profil tourné à 90°, sur un panneau ancré à gauche/droite\n- `dots(\"Niveaux\", valeur)` — (name, value, options?) — points non reliés (scatter), avec de vrais trous quand le script n'émet pas. Taille du point : options.lineWidth (rayon = lineWidth × 0,9, plancher 0,75 px ; défaut 1,5).\n- `.upper` — (offset?) => number | null — band\n- `.middle` — (offset?) => number | null — band\n- `.lower` — (offset?) => number | null — band\n- `.adx` — (offset?) => number | null — ADX\n- `.plusDI` — (offset?) => number | null — ADX\n- `.minusDI` — (offset?) => number | null — ADX\n- `plot.pane(\"\")` — (name, { dock? }) => handle — sub-pane dédié (bottom/left/right), dessiner via .line/.area/.histogram/.band/.label/.profile\n- `plot.overlay(\"\")` — (name) => handle — pane prix, dessiner via .line/.area/.histogram/.band/.label\n- `.area` — (name, value, options?) — pane.area/overlay.area\n- `.band` — (name, upper, lower, options?) — pane.band/overlay.band, remplit entre deux courbes\n- `.label(\"\", \"\", { x: 50, y: 50 })` — (name, texte, { x, y, unit?, rotation?, ... }) — pane.label/overlay.label, élément positionné librement\n- `plot.signal(\"BUY\")` — (\"BUY\"|\"SELL\" | {type,price?,color?,shape?})\n- `plot.point()` — (value, options?)\n- `plot.horizontal()` — (price, options?)\n- `plot.vertical()` — (options?)\n- `plot.table([], { title: \"\", columns: [] })` — (rows, options?) — table overlay anchored to a corner\n- `plot.xy(\"\", [], [])` — (name, x[], y[], options?) — graphique X/Y libre, mode notebook uniquement\n- `state.get(\"\", )` — (key, defaultValue?) => any\n- `state.set(\"\", )` — (key, value) => void\n- `alert()` — (message) => void\n- `console.log()` — (...) => void — capturé dans la console de l'éditeur\n- `bar.isNew()` — () => boolean\n- `bar.isClosed()` — () => boolean\n- `bar.isRealtime()` — () => boolean\n- `math.sma(, )` — (values, period) => number | null\n- `math.ema(, )` — (values, period) => number | null\n- `math.std()` — (values) => number | null\n- `math.variance()` — (values) => number | null\n- `math.mean()` — (values) => number | null\n- `math.median()` — (values) => number | null\n- `math.percentile(, )` — (values, p) => number | null\n- `math.zscore()` — (values) => number | null\n- `math.correlation(, )` — (a, b) => number | null\n- `math.covariance(, )` — (a, b) => number | null\n- `math.min()` — (values) => number | null\n- `math.max()` — (values) => number | null\n- `math.abs()` — (x) => number\n- `math.sqrt()` — (x) => number\n- `math.pow(, )` — (x, y) => number\n- `math.exp()` — (x) => number\n- `math.log()` — (x) => number\n- `ta.sma(, )` — (values, period) => number | null\n- `ta.ema(, )` — (values, period) => number | null\n- `ta.rsi(, )` — (values, period) => number | null\n- `ta.roc(, )` — (values, period) => number | null\n- `ta.atr(, , , )` — (high, low, close, period) => number | null\n- `ta.macd()` — (values, fast?, slow?, signal?) => {macd,signal,histogram} | null\n- `ta.bollinger()` — (values, period?, stdDev?) => {upper,middle,lower} | null\n- `ta.stochastic(, , )` — (high, low, close, period?, signalPeriod?) => {k,d} | null\n- `ta.adx(, , )` — (high, low, close, period?) => {adx,plusDI,minusDI} | null\n- `ta.wma(, )` — (values, period) => number | null\n- `ta.hma(, )` — (values, period) => number | null\n- `ta.alma(, )` — (values, period, offset?, sigma?) => number | null\n- `ta.swma()` — (values) => number | null — fenêtre fixe de 4 barres\n- `ta.vwma(, , )` — (values, volumes, period) => number | null\n- `ta.zlema(, )` — (values, period) => number | null\n\n---\n\n# Référence détaillée\n\n\n\n## Mots-clés disponibles\n\n## Tutoriel\n\nCe tutoriel construit deux indicateurs complets, de zéro — pas à pas, comme si quelqu'un l'expliquait à côté de vous. Chaque étape ci-dessous est directement éditable et exécutable : le code s'exécute automatiquement dès que vous arrivez sur une étape, contre un petit jeu de données de démonstration, et la chart juste à côté se met à jour en direct — modifiez-le, cliquez sur « Exécuter », observez le résultat, puis passez à l'étape suivante. Chaque fonction utilisée ici est réexpliquée en détail, avec son propre schéma, dans sa section dédiée plus bas — ce tutoriel est le fil conducteur, pas la référence exhaustive. Commencez ici : c'est la manière la plus rapide de comprendre comment tout s'articule.\n\n## Vue d'ensemble\n\nUn script est un programme JavaScript qui s'exécute une fois par bougie, du début à la fin de l'historique visible, exactement comme un indicateur intégré (RSI, MACD…) — sauf que vous en écrivez la logique vous-même. Il peut lire le prix et les indicateurs déjà présents sur la chart, dessiner ses propres courbes/signaux, mémoriser un état d'une bougie à l'autre, et déclencher des alertes.\n\nConcrètement, le moteur rejoue tout l'historique visible bougie par bougie, de la plus ancienne à la plus récente : à chaque étape, il ré-exécute votre code en entier avec « la bougie courante » pointée sur cette bougie-là, un peu comme si vous relisiez un journal jour par jour plutôt que de lire directement la dernière page. C'est ce rejeu, pas un calcul global sur tout le tableau d'un coup, qui garantit qu'un script ne peut jamais accidentellement regarder une bougie plus loin que celle en cours.\n\nTrois garanties structurelles, valables quel que soit le script écrit :\n\n- Aucune fuite de données futures — à la bougie i, aucune fonction de l'API ne peut jamais retourner une valeur d'une bougie postérieure à i. Ce n'est pas une vérification a posteriori : c'est structurellement impossible, les fonctions n'ont tout simplement pas accès aux données futures.\n- Synchronisation garantie — market.close(0), chart.indicator(\"rsi\").value(0) et n'importe quel autre accès à \"la bougie courante\" pointent toujours exactement sur la même bougie, quel que soit l'ordre des appels.\n- Bac à sable isolé — le script s'exécute dans un Web Worker séparé, sans accès réseau (fetch, XMLHttpRequest, WebSocket…), sans accès au stockage du navigateur (indexedDB, caches), et sans aucun moyen d'atteindre le code ou les données internes de l'application hôte.\n\nUne fois enregistré, un script se ré-exécute automatiquement à chaque nouvelle bougie (rejeu complet, avec un court délai anti-rafale) — pas besoin de cliquer sur « Exécuter » à chaque tick d'un marché en direct.\n\nChaque script activé tourne dans son propre Web Worker, indépendamment des autres : un script en erreur ou lent n'affecte ni les autres scripts actifs, ni le rendu de la chart elle-même. Sur un espace de travail à plusieurs graphiques, un script choisit une seule chart cible (voir « Cible » dans la barre d'outils) — il ne lit et n'affecte jamais que celle-là, jamais les autres panneaux ouverts en même temps.\n\n## L'éditeur\n\nLe code affiché dans l'éditeur est un brouillon, distinct du code réellement enregistré sur le script tant que vous n'avez pas cliqué sur « Enregistrer ».\n\n- Exécuter — lance le brouillon actuel tel quel, même non enregistré. C'est ce qui permet de tester une modification avant de la valider.\n- Exécuter la cellule (Maj+Entrée) — n'exécute qu'une portion du script à la fois, voir « Mode cellules » ci-dessous.\n- Arrêter — interrompt immédiatement une exécution en cours (utile en cas de boucle infinie) en terminant le Worker sous-jacent, plutôt que d'attendre qu'il se termine de lui-même.\n- Enregistrer — valide le brouillon comme code officiel du script (répercuté vers l'application hôte).\n- Réinitialiser — abandonne le brouillon et revient au dernier code enregistré.\n- Format — ré-indente légèrement le code (pas une mise en forme complète à la Prettier).\n\nSi l'exécution dépasse un certain délai (8 secondes pour un rejeu complet, 1,5 seconde pour une simple ré-évaluation en direct), elle est automatiquement interrompue et une erreur de délai dépassé s'affiche — c'est le filet de sécurité contre une boucle infinie qu'un script maladroit pourrait contenir.\n\nToute erreur (de syntaxe ou d'exécution) s'affiche sous l'éditeur avec son message et, quand le moteur JavaScript le permet, le numéro de ligne exact.\n\n### Mode cellules — exécuter un bloc à la fois (façon Jupyter)\n\n@block en début de ligne délimite une « cellule » ; ce qui suit sur la même ligne en est le titre, texte libre. Une fine bordure marque chaque cellule, et celle où se trouve le curseur est légèrement teintée — repérage visuel immédiat, sans rien avoir à cliquer. Comme @description, c'est un mot-clé lu dans le texte du script puis retiré avant compilation, pas du JavaScript.\n\n```js\n@block Étape 1 — les données de base\nconst closes = market.series(\"close\", 20);\nconst sma = math.sma(closes, 20);\n\n@block Étape 2 — le tracé\nplot.overlay(\"SMA 20\").line(\"SMA 20\", sma ?? market.close(0));\n```\n\nMaj+Entrée (ou le bouton « Exécuter la cellule ») exécute le code depuis le tout début du fichier jusqu'à la fin de la cellule où se trouve le curseur — pas cette seule cellule isolée. C'est une différence volontaire avec un vrai notebook Jupyter : ce moteur n'a pas de mémoire de variables entre deux exécutions (state.* lui-même repart de zéro à chaque exécution complète, voir state.* plus bas), donc une cellule isolée qui lirait une variable définie plus haut échouerait aussitôt. « Depuis le début jusqu'ici » reproduit exactement l'usage réel d'un notebook (on exécute ses cellules dans l'ordre, du haut vers le bas) sans dépendre d'un mécanisme que ce moteur n'a pas — écrivez votre script cellule par cellule, en appuyant sur Maj+Entrée à chaque étape pour voir immédiatement son effet sur la chart, exactement comme dans Jupyter.\n\nUn petit bouton ▶ apparaît directement sur la cellule active — cliquer dessus fait exactement la même chose que Maj+Entrée, sans avoir à viser le bouton « Exécuter la cellule » de la barre d'outils. Juste en dessous de la cellule, son propre résultat s'affiche : le texte de console.log, la valeur de la toute dernière expression de la cellule si elle n'est ni affectée à une variable ni déjà affichée autrement (exactement comme un vrai notebook auto-affiche le résultat d'une cellule qui se termine par une expression seule), et un graphique si la cellule contient un appel à plot.xy (voir plot.* plus bas). Voir le tutoriel « Mode notebook » plus haut pour un exemple pas à pas.\n\n### Mode no-code — le script en blocs reliés\n\nLe sélecteur « Code / No-code » en haut de la barre d'outils montre le même script de deux façons. En no-code, chaque cellule @block devient une boîte sur un plan de travail : on tire un bloc depuis la palette de gauche, on relie les boîtes entre elles en glissant du point de sortie de l'une vers le point d'entrée de l'autre, on clique une boîte pour en modifier le code dans l'éditeur du bas, et le ▶ de chaque boîte l'exécute.\n\nCe n'est pas un second format : les deux vues lisent et écrivent le même texte, et le basculement se fait à tout moment, y compris en pleine saisie. Ce qui rend cela possible, c'est que tout ce que le schéma sait est écrit sur la ligne @block elle-même — un identifiant, une position at x y, et les blocs dont il dépend avec after. Le mot-clé garde donc exactement sa forme d'origine : @block Titre reste valide, et un script écrit avant l'existence du mode no-code s'y ouvre tel quel, sous la forme d'une chaîne.\n\n```js\n@block(prix at 40 120) Charger les prix\nconst prix = market.close(0);\n\n@block(moyenne at 340 120) Moyenne mobile\nconst sma = ta.sma(market.series(\"close\", 60), 20);\n\n// « after » n'est nécessaire que lorsque l'ordre voulu n'est pas celui de l'écriture :\n// sans lui, un bloc suit simplement celui écrit juste avant.\n@block(signal at 640 120 after moyenne prix) Signal\nif (bar.isNew() && prix > sma) plot.signal(\"BUY\");\n```\n\nUne flèche veut dire « s'exécute après », pas « envoie ses données à ». Les blocs sont les cellules d'un même script et partagent une seule portée : une flèche de A vers B dit que B peut utiliser ce que A a déclaré, et fixe l'ordre en conséquence. Le ▶ d'un bloc exécute donc ce bloc et tout ce dont il dépend, dans l'ordre — la même règle que Maj+Entrée en mode code, généralisée au graphe.\n\nLa boîte en pointillés « Préambule » regroupe tout ce qui précède le premier @block : @indicator, @description, les imports, les déclarations new Variable(...). Elle s'exécute avant tous les blocs, ne peut pas être supprimée et n'a pas besoin d'être reliée — c'est pourquoi elle reste à sa place au lieu de se déplacer. Supprimer un bloc au milieu d'une chaîne relie ses enfants à ses parents : la chaîne se referme au lieu de se couper.\n\n### Plusieurs fichiers dans un même script\n\nUn script n'est pas obligé de tenir dans un seul fichier. La barre juste au-dessus du code donne un onglet par fichier : « Principal » est celui qui s'exécute, le bouton + en crée un nouveau, un double-clic sur un onglet le renomme et la croix le supprime. Les fichiers sont enregistrés avec le script et voyagent avec lui.\n\nUn fichier s'utilise avec la syntaxe des modules JavaScript : export dans le fichier qui fournit, import dans celui qui consomme. Le nom d'un fichier est ce qui suit ./ dans l'import — ./outils, outils et outils.js désignent tous les trois le fichier nommé outils.\n\n```js\nimport { Tracker } from \"./outils\";\n\nconst suivi = state.get(\"suivi\") ?? new Tracker(20);\nstate.set(\"suivi\", suivi);\nplot.overlay(\"Plus haut\").line(\"max\", suivi.pousser(market.close(0)));\n```\n\n```js\n// ./outils — un onglet à part dans l'éditeur\nexport class Tracker {\n  constructor(taille) {\n    this.taille = taille;\n    this.max = -Infinity;\n  }\n\n  pousser(valeur) {\n    this.max = Math.max(this.max, valeur);\n    return this.max;\n  }\n}\n```\n\nLa règle importante tient en une phrase : le fichier principal est réexécuté une fois par bougie, les fichiers importés ne sont évalués qu'une seule fois par exécution. Une instance créée dans un fichier importé traverse donc tout l'historique, là où un new écrit dans le fichier principal repartirait de zéro à chaque bougie — c'est pourquoi l'exemple ci-dessus range la sienne dans state.\n\n- Formes acceptées — import x from \"./f\", import { a, b as c } from \"./f\", import * as ns from \"./f\", import \"./f\" (pour son seul effet), export const/let/var/function/class, export default, export { a, b as c }.\n- export * from \"./f\" est refusé : re-exporter tous les noms d’un fichier suppose de savoir ce qu’il exporte, ce qui n’est connu qu’une fois exécuté. Ré-exportez les noms un par un.\n- Deux fichiers qui s’importent mutuellement sont signalés comme import circulaire plutôt que de rendre des exports à moitié construits.\n- new Variable(...) fonctionne dans n’importe quel fichier : le réglage apparaît dans la même fenêtre de paramètres, quel que soit le fichier qui le déclare.\n- Les numéros de ligne d’une erreur restent ceux du fichier où elle s’est produite — la réécriture interne des import/export préserve le découpage en lignes.\n\n## Décrire et paramétrer un script\n\nCinq mots-clés ne font pas partie de l'API exécutée : ils se lisent dans le texte du script lui-même, avant que quoi que ce soit ne tourne. @indicator, @strategy ou @quant dit ce qu'est le script, @description le documente, new Variable(...) en expose les réglages, et @block le découpe en cellules (voir « L'éditeur » plus haut). Tous sont retirés du code avant compilation — aucun n'existe à l'exécution.\n\n### @indicator / @strategy / @quant — ce qu'est le script\n\nUn script est l'un des trois, déclaré sur sa propre ligne, en général tout en haut. @indicator dessine sur la chart : des courbes, des bandes, des marqueurs. @strategy fait la même chose et prend en plus des positions, qui sont rejouées sur un compte simulé et lues dans un panneau dédié ancré sous les bougies. @quant ne dessine rien du tout.\n\n```js\n@indicator\nplot.overlay(\"SMA\").line(\"SMA\", math.sma(market.series(\"close\", 20), 20));\n```\n\n```js\n@strategy\nif (market.close(0) > market.close(1)) strategy.long(\"Deux hausses\");\n```\n\nCe n'est pas une étiquette : c'est ce décorateur qui donne — ou refuse — l'accès à strategy.*. Un script @indicator n'a tout simplement pas cet objet, et l'appeler échoue en nommant ce qui manque, plutôt que d'ouvrir silencieusement une position que personne n'a demandée. Un script qui ne déclare rien est un indicateur : c'est ce qu'était tout script écrit avant l'existence de ces décorateurs, et ce que reste l'immense majorité d'entre eux. En déclarer plusieurs est une contradiction, signalée comme telle dans l'éditeur.\n\n### @quant — une analyse qui ne dessine pas\n\nUne analyse @quant n'a ni pane ni overlay : elle ne produit rien sur la chart, et plot.* n'y est pas disponible — l'éditeur le signale avant l'exécution, et l'appeler échoue en nommant ce qu'il faut faire à la place. Ce qu'elle renvoie avec return est la totalité de son résultat.\n\nElle ne tourne pas non plus une fois par bougie mais une fois par symbole, positionnée sur la dernière bougie de chacun — market.* voit donc tout l'historique d'un coup. Les symboles se déclarent entre parenthèses ; sans liste, l'analyse tourne sur le symbole de la chart. Les bougies des autres symboles viennent de l'application (prop quantData) : cette bibliothèque n'a pas de source de données, et un symbole sans données revient avec sa propre ligne « aucune donnée » au lieu de faire échouer toute l'analyse.\n\n```js\n@quant(AAPL, MSFT, NVDA)\nconst closes = market.series(\"close\", 260);\nconst last = closes[closes.length - 1];\nreturn { cours: last, \"plus haut\": Math.max(...closes) };\n```\n\nLe résultat s'affiche dans l'éditeur, à côté du code, une section par symbole. Une analyse peut être longue et sa réponse est un constat daté, pas une lecture en direct : chaque calcul peut donc être enregistré et relu plus tard sans être refait, depuis la même section.\n\n### @report — écrire un document\n\nUn @report ne dessine rien non plus, et ne renvoie rien : il écrit un document. Il s'exécute une fois, positionné sur la dernière bougie — market.* et company.* voient donc tout l'historique — et chaque appel à report.* ajoute une section, dans l'ordre où elle sera lue.\n\nSept blocs, et pas davantage : un titre, des sous-titres, du texte, une grille de chiffres clés, un tableau, une petite série dessinée, et un encart pour conclure. C'est ce qu'un rapport contient ; tout le reste s'écrit en toutes lettres. Le document s'affiche à côté du code et s'exporte en PDF — c'est le navigateur qui imprime, donc le texte reste sélectionnable et la pagination est la vraie.\n\n```js\n@report\nreport.title(\"Analyse fondamentale\", { symbol: market.symbol() });\nreport.metrics([{ label: \"Chiffre d'affaires\", value: company.value(\"totalRevenue\") }]);\nreport.table([\"Exercice\", \"CA\"], [[\"N\", company.value(\"totalRevenue\")]]);\nreport.callout(\"positive\", \"Rentabilité élevée\", \"Le ROIC dépasse 20 % depuis quatre ans.\");\n```\n\n### ai.* — dans un script\n\nUn @quant et un @report peuvent interroger un modèle et attendre sa réponse — c'est le seul appel du bac à sable qui sort du worker. Voir la section ai.* pour les trois fonctions, leurs paramètres et leurs pièges.\n\n### @description — documenter le script\n\nÉcrit tout en haut du script, @description \"…\" donne le texte qui s'affiche quand on clique sur le petit cercle « ? » de l'en-tête d'une pane produite par ce script. Un script n'en déclare qu'une seule.\n\n```js\n@description \"///Mon indicateur///\nUn paragraphe d'explication. Une ligne seule passe à la ligne,\nune ligne vide ouvre un nouveau paragraphe.\n\n//Un sous-titre//\n**gras**, *italique*, __souligné__, --rayé--.\n\"\n```\n\nLe balisage accepté, volontairement réduit à six marques :\n\n- ///titre/// — un gros titre.\n- //sous-titre// — un sous-titre.\n- **texte** — gras.\n- *texte* — italique.\n- __texte__ — souligné.\n- --texte-- — rayé.\n\nUne ligne vide sépare deux paragraphes ; un simple retour à la ligne reste dans le même paragraphe. Ce n'est pas du Markdown et le texte n'est jamais interprété comme du HTML : seules ces six marques produisent quelque chose, tout le reste s'affiche tel quel.\n\n### new Variable — exposer un réglage\n\nUne constante déclarée avec new Variable(type, valeur par défaut) apparaît comme un champ réglable dans deux endroits : le panneau « Paramètres » de l'éditeur, et l'onglet « Entrées » de la fenêtre de réglages de chaque pane produite par le script. Changer une valeur relance le script tout seul — pas besoin de recliquer sur « Exécuter ».\n\n```js\nconst ATR_MULT = new Variable(\"number\", 3.0, { description: \"Largeur du noyau, en multiples d'ATR.\", min: 0.1, max: 10 });\nconst PALIERS = new Variable(\"Array[number]\", [0.5, 1, 2]);\nconst COULEUR = new Variable(\"color\", \"#3b82f6\");\nconst AFFICHER_SIGNAUX = new Variable(\"boolean\", true);\n\n// La variable s'utilise comme la constante qu'elle est :\nconst highs = market.series(\"high\", 14);\nconst lows = market.series(\"low\", 14);\nconst closes = market.series(\"close\", 14);\nconst bandwidth = (ta.atr(highs, lows, closes, 14) ?? 1) * ATR_MULT;\nif (AFFICHER_SIGNAUX) plot.signal(\"BUY\");\n```\n\nLes six types disponibles, et ce que la valeur par défaut doit être :\n\n- \"number\" — un nombre, négatif accepté. Champ numérique.\n- \"string\" — un texte entre guillemets. Champ texte.\n- \"boolean\" — true ou false, sans guillemets. Case à cocher.\n- \"color\" — une couleur hexadécimale, #rrggbb ou #rgb. Sélecteur de couleur.\n- \"Array[number]\" — un tableau de nombres, par exemple [1, 2, 3].\n- \"Array[string]\" — un tableau de textes, par exemple [\"a\", \"b\"].\n\nLe troisième argument est facultatif : { description: \"…\" }, dont le texte s'affiche sous le champ correspondant, et — uniquement pour \"number\" — { min, max }, qui bornent à la fois le champ (ses boutons +/- s'arrêtent à la limite, une valeur tapée hors bornes est ramenée dedans) et la valeur par défaut elle-même. Les trois se combinent librement : { description: \"…\", min: 0, max: 100 }.\n\nRègles, signalées comme des erreurs directement dans l'éditeur, avant même d'exécuter :\n\n- La déclaration doit être un const. let et var sont refusés — un réglage ne change pas en cours de route.\n- La valeur par défaut doit correspondre au type déclaré : new Variable(\"string\", 5) est une erreur, new Variable(\"string\", \"5\") non.\n- min/max ne s'appliquent qu'à un \"number\" — les poser sur un autre type est une erreur, tout comme min supérieur à max ou une valeur par défaut hors de cet intervalle.\n- Une variable déclarée ne peut plus être réaffectée ailleurs dans le script — ni par =, ni par +=, ni par ++ ou --. Sa valeur se change dans les réglages, pas dans le code.\n\nÀ l'exécution, chaque new Variable(...) est remplacé par la valeur effective — celle des réglages, ou celle écrite dans le code si elle n'a jamais été modifiée. La variable est donc une vraie constante JavaScript ordinaire : elle s'utilise directement dans un calcul, sans .value ni rien à déballer.\n\n### DEBOUNCE_MS — pacer les ticks en direct\n\nDEBOUNCE_MS est le seul nom que le moteur lit lui-même, plutôt que de se contenter de le substituer dans le code comme tout le reste : il règle le délai d'anti-rafale avant un recalcul déclenché par un tick de marché en direct sur la bougie encore en formation. Sans déclaration, ce délai est de 300 ms pour tout script.\n\n```js\nconst DEBOUNCE_MS = new Variable(\"number\", 0, { min: 0 });\n// Avec 0, le script se relance à chaque tick en direct, sans anti-rafale.\n```\n\nSans effet sur le replay ou l'arrivée d'une nouvelle bougie, qui relancent toujours le script immédiatement quelle que soit cette valeur — seul un vrai tick sans nouvelle bougie ni déplacement de replay passe par ce délai.\n\n## market.*\n\nLes prix, lus depuis la barre en cours d'exécution. Le script est rejoué barre par barre depuis le début de l'historique : à chaque passage, « la barre en cours » avance d'un cran, et tous les accesseurs ci-dessous se déplacent avec elle.\n\nC'est ce qui rend l'absence de fuite vers le futur structurelle : l'indice courant ne peut pas être avancé depuis un script. Un décalage négatif ne renvoie pas une erreur, il renvoie null — il n'y a rien à cet endroit.\n\n### market.open(offset?)\n\nLe prix d'ouverture d'une barre.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un nombre, ou null si l'offset sort de l'historique disponible. Un offset négatif renvoie toujours null : un script ne peut pas lire l'avenir, et cette limite est structurelle, pas une vérification qu'on aurait pu oublier.\n\n### market.high(offset?)\n\nLe plus haut atteint pendant la barre.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un nombre, ou null si l'offset sort de l'historique disponible. Un offset négatif renvoie toujours null : un script ne peut pas lire l'avenir, et cette limite est structurelle, pas une vérification qu'on aurait pu oublier.\n\n### market.low(offset?)\n\nLe plus bas atteint pendant la barre.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un nombre, ou null si l'offset sort de l'historique disponible. Un offset négatif renvoie toujours null : un script ne peut pas lire l'avenir, et cette limite est structurelle, pas une vérification qu'on aurait pu oublier.\n\n### market.close(offset?)\n\nLe prix de clôture. C'est l'accesseur le plus utilisé : sauf raison contraire, un calcul se fait sur les clôtures, qui sont le seul prix sur lequel le marché s'est réellement mis d'accord.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un nombre, ou null si l'offset sort de l'historique disponible. Un offset négatif renvoie toujours null : un script ne peut pas lire l'avenir, et cette limite est structurelle, pas une vérification qu'on aurait pu oublier.\n\n```js\nconst variation = market.close(0) - market.close(1);\n```\n\n### market.volume(offset?)\n\nLe volume échangé pendant la barre.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un nombre, null si l'offset sort de l'historique, et null aussi si l'application n'a pas fourni de volume — tous les instruments n'en ont pas.\n\n### market.time(offset?)\n\nL'horodatage d'une barre, en objet Date. Sert à borner un calcul dans le temps, ou à étiqueter une sortie avec la date à laquelle elle correspond.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours d'exécution, 1 = la précédente, et ainsi de suite.\n\nRenvoie : un objet Date, ou null si l'offset sort de l'historique.\n\n```js\nconst jour = market.time(0);\nif (jour !== null && jour.getUTCDay() === 1) plot.signal(\"lundi\");\n```\n\n### market.series(field, count?)\n\nUne fenêtre de valeurs d'un coup, plutôt qu'un accès barre par barre. C'est ce qu'attendent toutes les fonctions ta.* et math.*, et c'est bien plus rapide qu'une boucle d'appels individuels.\n\nParamètres :\n\n- field — quelle grandeur : \"open\", \"high\", \"low\", \"close\" ou \"volume\".\n- count — combien de barres, en remontant depuis la barre en cours. Le tableau renvoyé est ordonné de la PLUS ANCIENNE à la PLUS RÉCENTE.\n\nRenvoie : un tableau de nombres, éventuellement plus court que count si l'historique ne suffit pas, éventuellement vide. Jamais null.\n\n```js\nconst closes = market.series(\"close\", 60);\nconst dernier = closes[closes.length - 1]; // équivaut à market.close(0)\n```\n\nLe nombre de points est plafonné par le moteur (voir « Sécurité et limites ») : demander cent mille barres n'en renvoie pas cent mille. Et vérifiez la longueur réelle avant d'indexer : en début d'historique, le tableau est plus court que demandé.\n\n### market.heikinAshi(count?)\n\nLes chandeliers Heikin-Ashi calculés sur les mêmes barres : un lissage qui atténue le bruit et rend la tendance plus lisible. C'est un accesseur et non un calcul à refaire soi-même, parce que l'ouverture Heikin-Ashi dépend de la précédente, donc de toutes les barres antérieures — un script lisant une fenêtre fixe ne peut pas la reproduire.\n\nParamètres :\n\n- count — combien de barres renvoyer, en remontant depuis la barre en cours.\n\nRenvoie : un objet { open, high, low, close } de quatre tableaux alignés barre par barre, ordonnés du plus ancien au plus récent.\n\n```js\nconst ha = market.heikinAshi(60);\nconst corpsHaussier = ha.close[ha.close.length - 1] > ha.open[ha.open.length - 1];\n```\n\n### market.symbol()\n\nLe symbole affiché, tel que l'application l'a nommé. Un @report s'en sert pour se titrer ; une analyse @quant, qui s'exécute une fois par symbole, s'en sert pour savoir lequel elle est en train de traiter.\n\nRenvoie : une chaîne, ou null si l'application n'a nommé aucun symbole.\n\n```js\nreport.title(\"Analyse\", { symbol: market.symbol() });\n```\n\nLecture seule : connaître un nom de symbole ne donne aucun accès à ses données.\n\n### market.availableTimeframes()\n\nLes unités de temps que le sélecteur du graphique propose. Permet à un script de s'adapter à ce que l'application offre plutôt que de supposer.\n\nRenvoie : un tableau de chaînes au format \"<n><unité>\", par exemple [\"5m\", \"1h\", \"1d\"]. Vide si aucune n'a été configurée.\n\n### market.resample(interval)\n\nAgrège les barres du graphique en une unité de temps plus large, et renvoie un accesseur qui se lit exactement comme market.* lui-même. C'est ainsi qu'on regarde la tendance en journalier tout en travaillant en horaire, sans jamais quitter les données affichées.\n\nParamètres :\n\n- interval — l'unité voulue, au format \"<n><unité>\" avec l'unité parmi \"m\", \"h\" ou \"d\" : \"15m\", \"4h\", \"1d\".\n\nRenvoie : un objet exposant open, high, low, close, volume, time, series et heikinAshi, avec la même signature que market.* — mais sur les barres agrégées.\n\n```js\nconst journalier = market.resample(\"1d\");\nconst tendance = ta.ema(journalier.series(\"close\", 100), 50);\n```\n\nDeux cas renvoient un accesseur qui répond « aucune donnée » (null et tableaux vides) plutôt que de lever une erreur : un intervalle illisible, et un intervalle PLUS FIN que celui du graphique — il n'y a rien de réel en quoi subdiviser une barre, et fabriquer de la précision serait pire que de dire non. Les barres agrégées ne sont construites que jusqu'à la barre en cours : là encore, aucune fuite vers le futur possible.\n\n```js\n// Le motif complet : lire large, calculer, tracer.\nconst closes = market.series(\"close\", 100);\nconst rapide = ta.ema(closes, 12);\nconst lente = ta.ema(closes, 26);\nif (rapide !== null && lente !== null) {\n  plot.overlay(\"Moyennes\").line(\"Rapide\", rapide);\n  plot.overlay(\"Moyennes\").line(\"Lente\", lente);\n}\n```\n\n## chart.*\n\nLit les indicateurs DÉJÀ affichés sur le graphique, au lieu de les recalculer. La différence avec ta.* est importante : ta.rsi calcule un RSI que personne ne voit, chart.indicator(\"rsi\") lit celui que l'utilisateur a ajouté, avec les réglages qu'il a choisis. Si vous voulez que votre script réagisse à ce qui est à l'écran, c'est par ici.\n\nUn indicateur produit par un autre script n'apparaît pas ici : seuls les indicateurs intégrés sont lisibles. C'est une limite assumée, pas un oubli — sans elle, deux scripts pourraient se lire l'un l'autre en boucle.\n\n### chart.listIndicators()\n\nLes identifiants des indicateurs actuellement sur la chart. À appeler avant de supposer qu'un indicateur est là : l'utilisateur peut l'avoir retiré.\n\nRenvoie : un tableau d'identifiants, par exemple [\"sma\", \"rsi\", \"macd\"]. Vide si le graphique n'en affiche aucun.\n\n```js\nif (chart.listIndicators().includes(\"rsi\")) {\n  const rsi = chart.indicator(\"rsi\").value();\n}\n```\n\n### chart.indicator(id)\n\nUne poignée de lecture sur un indicateur affiché. Les méthodes qu'elle expose dépendent de la forme de l'indicateur — une simple courbe n'a qu'une valeur, une bande en a trois, un MACD trois autres.\n\nParamètres :\n\n- id — l'identifiant renvoyé par chart.listIndicators().\n\nRenvoie : toujours une poignée, jamais null. Un identifiant inconnu renvoie une poignée dont toutes les méthodes valent null : une faute de frappe ne casse pas le script, elle le rend silencieux.\n\n```js\nconst rsi = chart.indicator(\"rsi\");\nconst maintenant = rsi.value();\nconst ilYAUneBarre = rsi.value(1);\n```\n\n### …​.value(offset?)\n\nLa lecture d'un indicateur à courbe unique — sma, ema, rsi, atr… Sur un indicateur en bande, c'est sa ligne médiane, par la même convention que les étiquettes de survol du graphique.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours.\n\nRenvoie : un nombre, ou null — si l'indicateur n'a pas cette composante, s'il n'a pas encore de valeur à cette barre (période de chauffe), ou si l'offset sort de l'historique.\n\n### …​.upper(offset?) / .middle(offset?) / .lower(offset?)\n\nLes trois lignes d'un indicateur en bande — bandes de Bollinger, canal de Keltner. upper et lower bornent, middle est la moyenne autour de laquelle elles s'écartent.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours.\n\nRenvoie : un nombre, ou null — si l'indicateur n'a pas cette composante, s'il n'a pas encore de valeur à cette barre (période de chauffe), ou si l'offset sort de l'historique.\n\n```js\nconst bb = chart.indicator(\"bollinger\");\nconst haut = bb.upper();\nif (haut !== null && market.close(0) > haut) plot.signal(\"au-dessus de la bande\");\n```\n\n### …​.line(offset?) / .signal(offset?) / .histogram(offset?)\n\nLes trois composantes d'un MACD : la ligne principale, sa moyenne de signal, et l'écart entre les deux. Le passage de l'histogramme par zéro est exactement le croisement des deux lignes.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours.\n\nRenvoie : un nombre, ou null — si l'indicateur n'a pas cette composante, s'il n'a pas encore de valeur à cette barre (période de chauffe), ou si l'offset sort de l'historique.\n\n### …​.adx(offset?) / .plusDI(offset?) / .minusDI(offset?)\n\nLes trois composantes d'un ADX affiché : la force de la tendance, et les deux directionnelles qui en donnent le sens.\n\nParamètres :\n\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours.\n\nRenvoie : un nombre, ou null — si l'indicateur n'a pas cette composante, s'il n'a pas encore de valeur à cette barre (période de chauffe), ou si l'offset sort de l'historique.\n\n## plot.*\n\nTout ce qu'un script dessine passe par ici. Deux familles à ne pas confondre : les SÉRIES, qui accumulent un point par barre et forment une courbe, et les MARQUEURS, qui posent un élément unique à l'endroit où on est. Un appel à line() sur cinq cents barres donne une courbe de cinq cents points ; un appel à signal() sur cinq cents barres donne cinq cents marqueurs.\n\nUne série vit dans un panneau. plot.pane() en crée un sous les bougies, avec sa propre échelle — c'est ce qu'il faut à un RSI, qui n'a rien à voir avec l'échelle des prix. plot.overlay() dessine sur les bougies elles-mêmes, à l'échelle des prix — c'est ce qu'il faut à une moyenne mobile.\n\nNi l'un ni l'autre n'existe dans un @quant ni dans un @report : ces deux-là ne dessinent rien, et y appeler plot.* échoue en nommant ce qu'il faut faire à la place.\n\n### plot.pane(name, options?)\n\nCrée — ou retrouve — un panneau sous les bougies, avec son échelle propre. Rappelée avec le même nom, y compris à une autre barre, elle rend le même panneau : c'est ce qui permet d'écrire plot.pane(\"RSI\").line(...) à chaque barre sans créer cinq cents panneaux.\n\nParamètres :\n\n- name — le nom du panneau, affiché dans son en-tête. C'est aussi son identité : même nom, même panneau.\n- options.dock — où l'accrocher : \"bottom\" (défaut) l'empile sous les prix ; \"left\" ou \"right\" le place dans une colonne verticale à côté du graphique, ce qu'il faut pour un profil.\n\nRenvoie : une poignée exposant line, area, histogram, dots, band, label et profile.\n\n```js\nplot.pane(\"RSI\").line(\"RSI\", ta.rsi(market.series(\"close\", 60), 14));\n```\n\n### plot.overlay(name)\n\nLa même poignée, mais dessinée SUR les bougies, à l'échelle des prix. À utiliser pour tout ce qui se compare directement au prix : moyennes, bandes, niveaux.\n\nParamètres :\n\n- name — le nom du groupe, affiché dans la légende en haut à gauche.\n\nRenvoie : la même poignée que plot.pane.\n\n```js\nplot.overlay(\"Moyennes\").line(\"SMA 20\", ta.sma(market.series(\"close\", 60), 20));\n```\n\n### …​.line(name, value, options?)\n\nAjoute un point à une courbe continue. L'appel le plus courant de toute l'API de dessin.\n\nParamètres :\n\n- name — le nom de la courbe dans ce panneau. Même nom = même courbe, un point de plus.\n- value — la valeur à cette barre, ou null pour un TROU : la courbe n'est pas tracée là et les deux côtés ne sont pas reliés.\n- options.color — couleur CSS de la courbe.\n- options.lineWidth — épaisseur du trait, en pixels.\n- options.lineStyle — \"solid\" (défaut), \"dashed\" ou \"dotted\".\n\nRenvoie : rien.\n\nnull n'est pas zéro. Passer 0 quand la valeur est indisponible dessine une courbe qui plonge à zéro ; passer null laisse le trou honnête que c'est.\n\n### …​.area(name, value, options?)\n\nComme line, mais remplie jusqu'à la base du panneau. À utiliser quand la grandeur se lit comme une quantité accumulée plutôt que comme un niveau.\n\nParamètres :\n\n- name — le nom de la série.\n- value — la valeur, ou null pour un trou.\n- options.color — couleur CSS de la courbe.\n- options.lineWidth — épaisseur du trait, en pixels.\n- options.lineStyle — \"solid\" (défaut), \"dashed\" ou \"dotted\".\n\nRenvoie : rien.\n\n### …​.histogram(name, value, options?)\n\nUne barre par chandelier, depuis zéro. La forme juste pour une grandeur qui change de signe — un histogramme MACD, un delta de volume : le passage par zéro se voit, ce qu'une courbe ne montre pas.\n\nParamètres :\n\n- name — le nom de la série.\n- value — la valeur, ou null pour un trou.\n- options.color — couleur CSS de la courbe.\n- options.lineWidth — épaisseur du trait, en pixels.\n- options.lineStyle — \"solid\" (défaut), \"dashed\" ou \"dotted\".\n\nRenvoie : rien.\n\n### …​.dots(name, value, options?)\n\nUn point isolé par barre, sans les relier. C'est la forme honnête pour une valeur qui n'existe pas à toutes les barres — un stop suiveur, un niveau détecté : une courbe relierait deux points entre lesquels il n'y a rien.\n\nParamètres :\n\n- name — le nom de la série.\n- value — la valeur à cette barre.\n- options.color — couleur CSS de la courbe.\n- options.lineWidth — épaisseur du trait, en pixels.\n- options.lineStyle — \"solid\" (défaut), \"dashed\" ou \"dotted\".\n\nRenvoie : rien.\n\n### …​.band(name, upper, lower, options?)\n\nUne zone remplie entre deux courbes, avec ses deux bords tracés et une médiane calculée. C'est une seule série, pas deux : elle se lit, se masque et se supprime d'un bloc.\n\nParamètres :\n\n- name — le nom de la bande.\n- upper — le bord supérieur à cette barre.\n- lower — le bord inférieur.\n- options.color — couleur du remplissage et des bords.\n- options.lineWidth — épaisseur des bords.\n\nRenvoie : rien. null pour les DEUX bords laisse un trou ; l'un seulement ne suffit pas à dessiner quoi que ce soit.\n\n```js\nconst b = ta.bollinger(market.series(\"close\", 60), 20, 2);\nif (b !== null) plot.overlay(\"Bollinger\").band(\"BB\", b.upper, b.lower);\n```\n\n### …​.label(name, text, options)\n\nUn texte placé précisément dans le panneau : un titre, une lecture chiffrée, une annotation. Contrairement aux séries, ce n'est pas un point par barre — le dernier appel portant un nom donné remplace le précédent.\n\nParamètres :\n\n- name — l'identité de l'étiquette. Même nom = même étiquette, remplacée.\n- text — ce qui est écrit.\n- options.x / options.y — la position dans le panneau.\n- options.unit — \"px\" pour des pixels depuis le coin haut-gauche, \"%\" pour une fraction de la taille du panneau.\n- options.bar / options.price — ancrage à une barre et à un prix plutôt qu'à une position fixe : l'étiquette suit alors le graphique quand on le déplace.\n- options.rotation — rotation en degrés.\n- options.color / options.fontSize — couleur et taille du texte.\n- options.align — \"left\", \"center\" ou \"right\".\n\nRenvoie : rien.\n\n### …​.profile(name, values, prices, options?)\n\nUn profil horizontal — profil de marché, profil de volume : combien s'est passé à chaque NIVEAU DE PRIX, indépendamment du temps. Ce n'est pas une série temporelle : elle se calcule une fois sur une plage de prix, elle n'a aucune barre à laquelle s'attacher.\n\nParamètres :\n\n- name — le nom du profil.\n- values — l'importance de chaque niveau (volume, temps passé…).\n- prices — les niveaux de prix, alignés sur values.\n- options.color / options.lineWidth — apparence des barres.\n- options.headroom — la fraction de la largeur du panneau que le profil laisse libre, pour ne pas coller au bord.\n\nRenvoie : rien.\n\nvalues et prices doivent avoir la même longueur. À utiliser dans un panneau accroché à gauche ou à droite (dock).\n\n### plot.signal(arg)\n\nUn marqueur à la barre en cours : c'est ainsi qu'un indicateur dit « ici ». La forme la plus courante d'annotation ponctuelle.\n\nParamètres :\n\n- arg — soit une chaîne courte (\"BUY\", \"SELL\", \"achat\"…), soit un objet { type, price, color, shape, text } pour choisir le prix d'ancrage, la couleur, la forme et le libellé.\n\nRenvoie : rien.\n\n```js\nif (croisement) plot.signal(\"achat\");\nplot.signal({ type: \"SELL\", price: market.high(0), text: \"divergence\" });\n```\n\n### plot.point(value, options?)\n\nUn point à un prix choisi, à la barre en cours. Comme signal, mais quand c'est le NIVEAU qui compte plutôt que l'évènement.\n\nParamètres :\n\n- value — le prix auquel poser le point.\n- options.color / options.shape / options.text — apparence et libellé.\n\nRenvoie : rien.\n\n### plot.horizontal(price, options?)\n\nUne ligne horizontale sur toute la largeur, à un prix donné : un support, une résistance, un objectif.\n\nParamètres :\n\n- price — le prix.\n- options.color — couleur CSS.\n\nRenvoie : rien.\n\n### plot.vertical(options?)\n\nUne ligne verticale à la barre en cours : marque un instant plutôt qu'un niveau — une annonce, un changement de régime.\n\nParamètres :\n\n- options.color — couleur CSS.\n\nRenvoie : rien.\n\n### plot.table(rows, options?)\n\nUn tableau posé dans un coin du graphique. Ni une série ni un marqueur : un affichage de synthèse, remplacé à chaque exécution plutôt qu'accumulé.\n\nParamètres :\n\n- rows — les lignes du tableau, chacune avec ses cellules et éventuellement une couleur.\n- options.title — un titre.\n- options.columns — les en-têtes de colonnes.\n- options.position — dans quel coin l'ancrer.\n\nRenvoie : rien.\n\n### plot.xy(name, x, y, options?)\n\nUn graphique X/Y indépendant du rejeu barre par barre : on lui passe deux tableaux entiers. C'est la forme pour un nuage de points ou une relation entre deux grandeurs, que l'axe du temps ne sait pas montrer.\n\nParamètres :\n\n- name — le nom du graphique.\n- x — les abscisses.\n- y — les ordonnées, alignées sur x.\n- options.draw — \"line\" ou \"scatter\".\n- options.color / options.title / options.xLabel / options.yLabel — apparence et légendes.\n\nRenvoie : rien.\n\n```js\nplot.xy(\"Rendement vs volume\", volumes, rendements, { draw: \"scatter\" });\n```\n\n```js\n// Un panneau, une bande, un marqueur — le trio le plus fréquent.\nconst closes = market.series(\"close\", 60);\nconst b = ta.bollinger(closes, 20, 2);\nif (b !== null) {\n  plot.overlay(\"Bollinger\").band(\"BB\", b.upper, b.lower, { color: \"#3b7dd8\" });\n  if (market.close(0) > b.upper) plot.signal({ type: \"SELL\", text: \"au-dessus de la bande\" });\n}\nplot.pane(\"RSI\").line(\"RSI\", ta.rsi(closes, 14));\n```\n\n## strategy.*\n\nDisponible uniquement dans un script ayant déclaré @strategy. C'est l'API qui prend des positions : le moteur les rejoue sur un compte simulé au fil des barres, et le panneau ancré sous la chart en montre la courbe de P&L, les statistiques et la liste des trades.\n\nCe n'est pas une étiquette : un script @indicator n'a tout simplement pas cet objet, et l'appeler échoue en nommant ce qui manque plutôt que d'ouvrir silencieusement une position que personne n'a demandée.\n\nLes ordres ne se règlent jamais au milieu d'une barre. Tout ce qu'un passage décide est exécuté APRÈS ce passage, au prix de règlement de la barre : un script qui change trois fois d'avis dans la même barre produit une seule opération, pas trois.\n\n### strategy.long(comment?, options?)\n\nOuvre — ou renforce — une position acheteuse. Si la position en cours est vendeuse, elle est retournée : fermée puis rouverte à l'achat, ce que « passer long » veut dire pour quiconque lit la phrase.\n\nParamètres :\n\n- comment — le libellé du trade, repris sur le marqueur posé sur la chart et dans la liste des trades. Facultatif mais fortement conseillé : c'est ce qui rend un backtest relisible.\n- options — la taille de l'entrée. Sans options, la taille par défaut des réglages de la stratégie s'applique.\n\nRenvoie : rien.\n\n```js\nif (rapide > lente && strategy.position() === \"flat\") strategy.long(\"croisement haussier\");\n```\n\n### strategy.short(comment?, options?)\n\nLe symétrique exact de long : ouvre ou renforce une position vendeuse, et retourne une position acheteuse en cours.\n\nParamètres :\n\n- comment — le libellé du trade.\n- options — la taille de l'entrée.\n\nRenvoie : rien.\n\n### strategy.close(comment?)\n\nFerme tout ce qui est ouvert, au prix de règlement de la barre. Sans effet si la position est déjà plate.\n\nParamètres :\n\n- comment — le libellé de la sortie, repris sur le marqueur et dans la liste des trades.\n\nRenvoie : rien.\n\n```js\nif (rapide < lente && strategy.position() === \"long\") strategy.close(\"croisement inverse\");\n```\n\n### strategy.position()\n\nLe sens de la position en cours. C'est la question à poser avant d'agir : sans elle, une condition vraie plusieurs barres de suite rouvre la même position à chaque passage.\n\nRenvoie : \"long\", \"short\" ou \"flat\".\n\n```js\nif (signal && strategy.position() === \"flat\") strategy.long(\"entrée\");\n```\n\nRenvoie une CHAÎNE, pas un nombre : comparer à 0 ne fonctionne pas, il faut comparer à \"flat\".\n\n### strategy.positionSize()\n\nLe nombre d'unités détenues. Toujours positif : c'est position() qui porte le sens.\n\nRenvoie : un nombre, 0 quand la position est plate.\n\n### strategy.averagePrice()\n\nLe prix moyen d'entrée de la position ouverte, entrées multiples comprises. C'est la référence pour un stop ou un objectif calculé depuis l'entrée réelle plutôt que depuis la première.\n\nRenvoie : un nombre, ou null quand la position est plate.\n\n```js\nconst entree = strategy.averagePrice();\nif (entree !== null && market.close(0) < entree * 0.95) strategy.close(\"stop à -5 %\");\n```\n\n### strategy.unrealizedProfit()\n\nLe gain ou la perte latente de la position ouverte, au prix courant. Sert à sortir sur un objectif de gain, ou à couper une perte, sans recalculer soi-même depuis le prix d'entrée.\n\nRenvoie : un nombre dans la devise du compte simulé. 0 quand la position est plate.\n\n```js\n// Une stratégie complète tient en peu de lignes.\n@strategy\nconst closes = market.series(\"close\", 60);\nconst rapide = ta.ema(closes, 12);\nconst lente = ta.ema(closes, 26);\nif (rapide !== null && lente !== null && bar.isClosed()) {\n  if (rapide > lente && strategy.position() === \"flat\") strategy.long(\"croisement haussier\");\n  if (rapide < lente && strategy.position() === \"long\") strategy.close(\"croisement baissier\");\n}\n```\n\n## company.*\n\nCe que l'entreprise a publié, lu à la barre en cours d'exécution. C'est le pendant fondamental de market.* : mêmes bornes, mêmes décalages, même garantie de ne jamais voir l'avenir.\n\nCette bibliothèque n'a aucune source de données : tout ce qui est lisible ici a été fourni par l'application (prop fundamentals du graphique). Un champ qu'elle n'a pas transmis n'existe pas — d'où company.fields(), à interroger avant de supposer.\n\nChaque publication est projetée en escalier sur les barres : la valeur reste celle du dernier rapport jusqu'au suivant, et vaut null avant le premier. C'est exactement ce que montrent les panneaux fondamentaux de la chart, si bien qu'un script et un panneau ne peuvent pas afficher deux chiffres différents pour la même barre.\n\n### company.value(field, offset?)\n\nUne métrique publiée, à la barre courante ou en arrière. C'est par là que passent le chiffre d'affaires, le résultat, les marges, le CAPEX, les impôts, la dette, le ROIC — tout ce que l'application a transmis.\n\nParamètres :\n\n- field — le nom de la métrique, tel que company.fields() le renvoie : \"totalRevenue\", \"netIncome\", \"capex\", \"taxExpense\", \"returnOnInvestedCapital\"…\n- offset — de combien de barres remonter. 0 (défaut) = la barre en cours. Un offset négatif renvoie null : on ne lit pas l'avenir.\n\nRenvoie : un nombre, ou null — si le champ n'a jamais été fourni, si la barre visée précède la première publication, ou si l'offset sort de l'historique.\n\n```js\nconst ca = company.value(\"totalRevenue\");\nconst caIlYAUnAn = company.value(\"totalRevenue\", 252);\nconst croissance = ca !== null && caIlYAUnAn ? (ca / caIlYAUnAn - 1) * 100 : null;\n```\n\nLe décalage se compte en BARRES, pas en exercices. « Il y a un an » dépend de l'unité de temps et de la longueur de l'historique : déduisez vos décalages de market.series(\"close\").length plutôt que de supposer 252 séances.\n\n### company.fields()\n\nLes métriques réellement disponibles pour ce symbole. Un rapport honnête commence par les regarder : c'est la différence entre dire « le CAPEX n'a pas été communiqué » et afficher un tiret sans explication.\n\nRenvoie : un tableau de noms de champs. Vide si l'application n'a transmis aucune donnée fondamentale.\n\n```js\nconst dispo = company.fields();\nif (!dispo.includes(\"capex\")) report.text(\"CAPEX non communiqué par la source de données.\");\n```\n\n## report.*\n\nDisponible uniquement dans un script ayant déclaré @report. Un rapport ne dessine rien et ne renvoie rien : il ÉCRIT UN DOCUMENT, section après section, dans l'ordre où elles seront lues. Il s'exécute une seule fois, positionné sur la dernière barre — market.* et company.* voient donc tout l'historique d'un coup.\n\nSept blocs, et pas davantage. C'est ce qu'un rapport contient : un titre, des intertitres, du texte, une grille de chiffres clés, un tableau, une petite série dessinée, et un encart pour conclure. Tout le reste s'écrit en toutes lettres — chaque forme supplémentaire serait une chose de plus que le panneau, la page imprimée et le modèle devraient tous comprendre de la même façon.\n\nLe document s'affiche à côté du code et s'exporte en PDF. C'est le navigateur qui imprime : le texte reste sélectionnable et la pagination est la vraie, pas une image.\n\n### report.title(title, options?)\n\nNomme le rapport. Appelée plusieurs fois, la dernière gagne — un script qui calcule son titre d'après les données qu'il vient de lire n'a donc pas à le connaître d'avance.\n\nParamètres :\n\n- title — le titre du document.\n- options.subtitle — une ligne sous le titre : la période couverte, la nature de l'analyse.\n- options.symbol — le symbole dont il est question, affiché à côté de la date de génération.\n\nRenvoie : rien.\n\n```js\nreport.title(\"Analyse fondamentale\", { subtitle: \"Quatre exercices\", symbol: market.symbol() });\n```\n\n### report.heading(text, options?)\n\nOuvre une section. C'est ce qui donne au document sa structure, et à la lecture ses points d'accroche.\n\nParamètres :\n\n- text — l'intertitre.\n- options.level — 2 (défaut) pour une section, 3 pour une sous-section.\n\nRenvoie : rien.\n\n### report.text(text)\n\nUn paragraphe. C'est là que se dit ce que les chiffres ne disent pas : pourquoi une évolution compte, ce qui manque, ce dont on n'est pas sûr.\n\nParamètres :\n\n- text — le paragraphe.\n\nRenvoie : rien.\n\n### report.metrics(metrics)\n\nUne grille de chiffres clés — ce qu'un lecteur regarde avant de lire quoi que ce soit. À placer en tête plutôt qu'au fil du texte.\n\nParamètres :\n\n- metrics — un tableau d'objets { label, value, note?, tone? }.\n- label — le nom de la mesure.\n- value — sa valeur, DÉJÀ FORMATÉE : c'est le script qui décide des unités et des décimales, le rapport n'arrondit rien dans votre dos.\n- note — une précision sous la valeur : une comparaison, une date de référence.\n- tone — \"up\", \"down\" ou \"neutral\" (défaut) : colore la valeur.\n\nRenvoie : rien. Au-delà de 24 entrées, les suivantes sont ignorées — ce n'est plus une grille de chiffres clés.\n\n```js\nreport.metrics([\n  { label: \"Chiffre d'affaires\", value: \"138 Md\", tone: \"up\" },\n  { label: \"ROIC\", value: \"27,3 %\", note: \"vs 21,4 % il y a quatre ans\" },\n]);\n```\n\n### report.table(columns, rows, options?)\n\nUn tableau de chiffres. La forme à préférer dès qu'on compare plusieurs périodes ou plusieurs postes.\n\nParamètres :\n\n- columns — les en-têtes, dans l'ordre.\n- rows — un tableau de lignes, chaque ligne étant un tableau de cellules alignées sur columns. Une cellule peut être une chaîne, un nombre, ou null pour une donnée absente (affichée « — »).\n- options.title — un titre au-dessus du tableau : l'unité, le périmètre.\n\nRenvoie : rien. Au-delà de 400 lignes, les suivantes sont ignorées.\n\n```js\nreport.table(\n  [\"Exercice\", \"CA\", \"Résultat net\"],\n  [[\"N-1\", 121, 27], [\"N\", 138, 32]],\n  { title: \"En milliards\" }\n);\n```\n\n### report.series(title, labels, values, options?)\n\nUne petite série dessinée — un chiffre d'affaires sur huit ans, un CAPEX sur quatre. Ce n'est pas un graphique complet : un rapport se lit, et le lecteur qui veut interroger une série a la chart pour ça.\n\nParamètres :\n\n- title — ce que la série représente.\n- labels — les étiquettes de l'axe, dans l'ordre.\n- values — les valeurs, alignées sur labels. null pour un point manquant.\n- options.unit — l'unité, affichée à côté de la dernière valeur.\n\nRenvoie : rien. Au-delà de 400 points, les suivants sont ignorés.\n\n```js\nreport.series(\"CAPEX\", [\"N-3\", \"N-2\", \"N-1\", \"N\"], [7.0, 8.2, 9.1, 10.4], { unit: \"Md\" });\n```\n\n### report.callout(tone, title, text)\n\nUn encart mis à part : le seul endroit où un rapport a le droit de CONCLURE plutôt que de rapporter. À réserver au jugement, pas à un fait de plus.\n\nParamètres :\n\n- tone — \"positive\", \"negative\" ou \"neutral\" : colore le liseré.\n- title — la conclusion en quelques mots.\n- text — ce qui la justifie.\n\nRenvoie : rien.\n\n```js\nreport.callout(\"positive\", \"Rentabilité durablement élevée\",\n  \"Un ROIC au-dessus de 20 % pendant quatre ans sans dilution est le signe d'une barrière à l'entrée.\");\n```\n\n## ai.*\n\nLe seul appel de tout le bac à sable qui sort du worker. Le script pose une question, la fenêtre principale la transmet au modèle configuré par l'application (prop ai du graphique), et renvoie la réponse. Le worker ne voit jamais de clé et n'ouvre jamais de connexion : une chaîne sort, une chaîne revient.\n\nIl faut l'attendre avec await, et c'est pourquoi ai.* n'existe que dans un @quant ou un @report : eux s'exécutent une seule fois. Un @indicator ou un @strategy s'exécute une fois par bougie — attendre une réponse réseau à chaque bougie ne serait plus un rejeu. L'éditeur le signale avant l'exécution.\n\nUne question qui échoue — aucun moteur configuré, refus du fournisseur — lève une erreur ordinaire, à attraper avec try/catch : un rapport qui interroge le modèle sur un point secondaire ne devrait pas mourir parce que ce point est resté sans réponse. Et le délai d'exécution du script continue de courir pendant l'attente : une réponse lente reste une exécution lente.\n\n### await ai.ask(prompt, options?)\n\nPose une question et attend la réponse en texte.\n\nParamètres :\n\n- prompt — la question.\n- options.search — à vrai, active la recherche web du fournisseur pour cette question. Faux par défaut : une recherche que l'auteur n'a pas demandée est une dépense qu'il n'a pas prévue.\n- options.system — remplace les instructions de rôle par défaut, si vous voulez cadrer la réponse autrement.\n\nRenvoie : une promesse de chaîne. Lève une erreur si aucun moteur n'est configuré ou si le fournisseur refuse.\n\n```js\nconst resume = await ai.ask(\"Résume l'activité de \" + market.symbol() + \" en trois phrases.\");\nreport.text(resume);\n```\n\n### await ai.search(query)\n\nUne question qui nécessite le web. Raccourci exact de ai.ask(query, { search: true }) — il existe parce que « cherche sur internet » est une intention à part entière et se lit mieux comme un verbe.\n\nParamètres :\n\n- query — ce qu'on cherche.\n\nRenvoie : une promesse de chaîne.\n\n```js\nconst actus = await ai.search(\"résultats trimestriels \" + market.symbol());\n```\n\nN'a d'effet que si l'application a activé les outils du fournisseur (prop ai.serverTools). Sans cela, la question part sans recherche.\n\n### await ai.json(prompt, options?)\n\nDemande une structure plutôt qu'un texte, et la parse. Utile quand la réponse doit alimenter un calcul ou un tableau plutôt qu'un paragraphe.\n\nParamètres :\n\n- prompt — la question, en précisant la forme attendue.\n- options.search / options.system — comme pour ask.\n\nRenvoie : une promesse de la valeur parsée, ou null si la réponse n'était pas du JSON valide. Le bloc de code dont un modèle entoure souvent le JSON est retiré automatiquement.\n\n```js\nconst note = await ai.json(\"Note la solidité du bilan sur 10. Réponds au format { note, raison }.\");\nif (note !== null) report.metrics([{ label: \"Solidité\", value: String(note.note) + \"/10\", note: note.raison }]);\n```\n\nRenvoie null plutôt que de lever : un modèle qui a répondu en prose a répondu, simplement pas dans la forme demandée.\n\n```js\n@report\n// Les trois formes, dans un rapport.\nconst resume = await ai.ask(\"Résume l'activité en trois phrases.\");\nconst actus = await ai.search(\"actualités récentes \" + market.symbol());\nconst note = await ai.json(\"Note la solidité du bilan sur 10, format { note, raison }.\");\n```\n\n## state.*\n\nLa mémoire d'un script d'une barre à l'autre. Le script est ré-exécuté à chaque barre, dans une portée neuve : une variable ordinaire ne survit pas d'un appel au suivant. state.* est le seul endroit où poser ce qui doit persister — un compteur, le prix d'entrée d'une position, l'état d'une machine.\n\nCette mémoire vit le temps d'une exécution complète, du premier au dernier chandelier. Elle repart de zéro à chaque nouvelle exécution : ce n'est pas une sauvegarde, c'est un accumulateur de rejeu.\n\n### state.get(key, defaultValue?)\n\nRelit ce qui a été posé aux barres précédentes.\n\nParamètres :\n\n- key — un nom de votre choix, unique dans ce script.\n- defaultValue — ce qui est renvoyé si la clé n'a jamais été écrite. Évite d'avoir à tester l'absence à chaque barre.\n\nRenvoie : la valeur telle qu'elle a été écrite, ou defaultValue, ou undefined si aucun défaut n'a été donné.\n\n```js\nconst barresDepuisSignal = state.get(\"depuis\", 0);\nstate.set(\"depuis\", barresDepuisSignal + 1);\n```\n\n### state.set(key, value)\n\nÉcrit une valeur que les barres suivantes reliront.\n\nParamètres :\n\n- key — le nom sous lequel relire.\n- value — n'importe quelle valeur : nombre, chaîne, booléen, objet, tableau. Elle est conservée telle quelle, sans copie.\n\nRenvoie : rien.\n\nLa valeur n'est pas copiée : si vous y rangez un objet et le modifiez ensuite, les barres suivantes verront la modification. C'est pratique pour un accumulateur, surprenant pour un instantané — rangez une copie si vous vouliez figer.\n\n## alert(message)\n\nSignale un évènement à l'application qui héberge le graphique. Le script produit l'évènement ; ce qu'il devient — une notification, un son, une ligne dans un journal, un e-mail — appartient entièrement à l'application (prop onScriptAlert).\n\n### alert(message)\n\nÉmet un évènement horodaté à la barre en cours. C'est le seul moyen pour un script de dire quelque chose au monde extérieur.\n\nParamètres :\n\n- message — le texte à transmettre. Converti en chaîne s'il ne l'est pas.\n\nRenvoie : rien.\n\n```js\nif (rsi !== null && rsi > 80) alert(\"RSI au-dessus de 80 sur \" + market.symbol());\n```\n\nLa liste des alertes est reconstruite depuis la première barre à chaque exécution : rejouer tout l'historique produit toutes les alertes de cet historique. Bornez avec bar.isRealtime() si vous ne voulez que le direct.\n\n## bar.*\n\nOù en est l'exécution : s'agit-il d'une barre qu'on découvre, d'une barre close, d'un rejeu ou du temps réel. Trois questions qui décident si une action doit être prise maintenant ou attendre.\n\n### bar.isNew()\n\nVrai à la première évaluation d'une barre donnée. Sert à n'agir qu'une fois par chandelier, quand un même chandelier peut être ré-évalué plusieurs fois en temps réel.\n\nRenvoie : un booléen.\n\n```js\nif (bar.isNew()) state.set(\"compteur\", state.get(\"compteur\", 0) + 1);\n```\n\n### bar.isClosed()\n\nVrai quand la barre en cours est terminée. C'est le garde-fou d'une stratégie : agir sur une barre encore en formation, c'est agir sur un prix qui peut encore repasser de l'autre côté du seuil avant la clôture.\n\nRenvoie : un booléen. Toujours vrai si l'application n'a pas indiqué que le marché est ouvert (prop lastCandleOpen) — le choix conservateur : un script qui attend la clôture ne doit pas rester bloqué faute d'information.\n\n```js\nif (bar.isClosed() && market.close(0) > seuil) strategy.long(\"cassure confirmée\");\n```\n\n### bar.isRealtime()\n\nDistingue le rejeu de l'historique d'une ré-exécution déclenchée par une nouvelle barre. Sert à ne déclencher une alerte que sur du direct, sans en émettre des centaines en rejouant deux ans d'archives.\n\nRenvoie : un booléen : faux pendant un rejeu historique ou une exécution manuelle, vrai sur un tick live.\n\n```js\nif (bar.isRealtime() && croisement) alert(\"croisement à l'instant\");\n```\n\n## math.*\n\nDes statistiques sur des tableaux de nombres, plus les fonctions numériques de base. À la différence de ta.*, rien ici ne suppose qu'il s'agit de prix : ce sont des outils généraux, qu'on applique aussi bien à des rendements, à des volumes ou à des écarts.\n\nToutes les fonctions statistiques renvoient null sur un tableau vide, ou trop court pour ce qu'elles calculent. Aucune ne modifie le tableau qu'on lui passe.\n\n### math.mean(values)\n\nLa moyenne arithmétique : la somme divisée par le nombre de valeurs. Le centre de gravité de la série.\n\nParamètres :\n\n- values — tableau de nombres.\n\nRenvoie : un nombre, ou null si le tableau est vide.\n\n```js\nconst moyenne = math.mean(market.series(\"close\", 20));\n```\n\n### math.median(values)\n\nLa médiane : la valeur qui coupe la série en deux. Contrairement à la moyenne, une seule valeur aberrante ne la déplace pas — c'est le centre à préférer quand la série contient des pics.\n\nParamètres :\n\n- values — tableau de nombres.\n\nRenvoie : un nombre, ou null si le tableau est vide. Sur un nombre pair de valeurs, la moyenne des deux valeurs centrales.\n\n```js\nconst volumeTypique = math.median(market.series(\"volume\", 60));\n```\n\n### math.std(values)\n\nL'écart-type : de combien les valeurs s'écartent en moyenne de leur moyenne. C'est la mesure de dispersion la plus courante, et la brique de toute mesure de volatilité.\n\nParamètres :\n\n- values — tableau de nombres.\n\nRenvoie : un nombre positif, ou null si le tableau est vide.\n\n```js\n// Volatilité annualisée à partir des rendements quotidiens :\nconst closes = market.series(\"close\", 260);\nconst rendements = closes.slice(1).map((c, i) => c / closes[i] - 1);\nconst vol = math.std(rendements) * Math.sqrt(252) * 100;\n```\n\n### math.variance(values)\n\nLa variance : l'écart-type au carré. Même information, dans une unité qui s'additionne — c'est la forme à utiliser pour combiner les dispersions de plusieurs séries.\n\nParamètres :\n\n- values — tableau de nombres.\n\nRenvoie : un nombre positif, ou null si le tableau est vide.\n\n### math.percentile(values, p)\n\nLa valeur en dessous de laquelle se trouve p % de la série. Sert à situer une lecture dans son propre historique : « le volume d'aujourd'hui est-il élevé pour ce titre ? » se répond en le comparant à son 90e centile, pas à une constante.\n\nParamètres :\n\n- values — tableau de nombres.\n- p — le centile voulu, entre 0 et 100.\n\nRenvoie : un nombre, ou null si le tableau est vide.\n\n```js\nconst vols = market.series(\"volume\", 250);\nconst seuil = math.percentile(vols, 90);\nif (seuil !== null && market.volume(0) > seuil) alert(\"volume dans le décile supérieur\");\n```\n\n### math.zscore(values, value?)\n\nÀ combien d'écarts-types de la moyenne se trouve une valeur. C'est la façon de comparer des grandeurs qui n'ont pas la même unité : un z-score de 2 sur le volume et un z-score de 2 sur la volatilité veulent dire la même chose, « inhabituellement haut ».\n\nParamètres :\n\n- values — tableau de nombres servant de référence.\n- value — la valeur à situer. Omise, c'est la dernière valeur du tableau qui est utilisée.\n\nRenvoie : un nombre (négatif en dessous de la moyenne), ou null si le tableau est vide ou son écart-type nul.\n\n```js\nconst z = math.zscore(market.series(\"volume\", 200));\n```\n\n### math.correlation(a, b)\n\nLe coefficient de corrélation entre deux séries : dans quelle mesure elles montent et descendent ensemble. Sert à mesurer une diversification réelle, ou à repérer que deux positions supposées indépendantes ne le sont pas.\n\nParamètres :\n\n- a — première série.\n- b — seconde série, alignée sur la première, de même longueur.\n\nRenvoie : un nombre entre −1 et 1, ou null si les tableaux sont vides, de longueurs différentes, ou si l'un est constant.\n\n```js\nconst r = math.correlation(market.series(\"close\", 120), autreSerie);\n```\n\nUne corrélation forte ne dit rien d'une cause. Et elle se calcule ici sur les valeurs telles quelles : sur des prix, deux séries qui montent toutes deux donneront une corrélation élevée même sans lien — comparez plutôt les rendements.\n\n### math.covariance(a, b)\n\nLa covariance : la corrélation avant normalisation, donc exprimée dans le produit des unités des deux séries. Utile comme brique de calcul (un bêta, une variance de portefeuille) ; illisible telle quelle.\n\nParamètres :\n\n- a — première série.\n- b — seconde série, de même longueur.\n\nRenvoie : un nombre, ou null si les tableaux sont vides ou de longueurs différentes.\n\n### math.min(values) / math.max(values)\n\nLe plus petit et le plus grand élément d'un tableau. Prennent le tableau lui-même, pas une liste d'arguments.\n\nParamètres :\n\n- values — tableau de nombres.\n\nRenvoie : un nombre, ou null si le tableau est vide.\n\n```js\nconst plusHaut = math.max(market.series(\"high\", 252)); // plus haut de l'année\n```\n\nÀ ne pas confondre avec Math.max(...) du langage, qui prend des arguments séparés : math.max(tableau) fonctionne, Math.max(tableau) renvoie NaN.\n\n### math.sma(values, period) / math.ema(values, period)\n\nLes deux mêmes moyennes que ta.sma et ta.ema. Elles existent ici parce qu'une moyenne mobile n'est pas seulement un indicateur : on lisse aussi un volume, une largeur de bande, un score composite. Le calcul est identique.\n\nParamètres :\n\n- values — tableau de nombres.\n- period — longueur de la fenêtre.\n\nRenvoie : un nombre, ou null si le tableau est plus court que la fenêtre.\n\n### math.abs / sqrt / pow / exp / log\n\nLes fonctions numériques du langage, exposées sous le même préfixe pour éviter d'avoir à mélanger math.* et Math.* dans une même expression. Comportement strictement identique à Math.abs, Math.sqrt, Math.pow, Math.exp et Math.log.\n\nParamètres :\n\n- Les mêmes que leurs équivalents Math.* : un nombre, sauf pow qui en prend deux.\n\nRenvoie : un nombre.\n\n## ta.*\n\nCes fonctions calculent un indicateur technique sans qu'il soit affiché sur la chart — utile pour composer plusieurs lectures dans un score sans encombrer l'écran de panneaux. Elles ne renvoient jamais une série : toujours la dernière valeur calculable, c'est-à-dire la lecture de la barre en cours.\n\nToutes prennent un tableau ordonné de la plus ancienne valeur à la plus récente — exactement l'ordre que market.series renvoie. Passer un tableau à l'envers ne lève aucune erreur : il calcule simplement l'indicateur d'un marché qui remonterait le temps.\n\nToutes renvoient null tant que la fenêtre n'est pas remplie. C'est la source d'erreur numéro un : un tableau de 20 valeurs ne donne pas de RSI(14) utilisable dès la première barre, et null + 1 vaut 1 en JavaScript, sans avertissement. Testez la valeur avant de vous en servir.\n\n```js\nconst closes = market.series(\"close\", 60);\nconst rsi = ta.rsi(closes, 14);\nif (rsi !== null && rsi < 30) plot.signal(\"achat\");\n```\n\n### ta.sma(values, period)\n\nLa moyenne arithmétique des « period » dernières valeurs. La référence à laquelle toutes les autres se comparent : chaque barre de la fenêtre compte autant, ce qui la rend lisse et lente. On s'en sert pour situer un niveau moyen, pas pour réagir vite.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — nombre de barres de la fenêtre. Doit être ≥ 1.\n\nRenvoie : un nombre, ou null si values contient moins de « period » valeurs.\n\n```js\nconst moyenne20 = ta.sma(market.series(\"close\", 50), 20);\n```\n\n### ta.ema(values, period)\n\nLa moyenne mobile exponentielle : chaque barre pèse un peu moins que la suivante, sans jamais tomber à zéro. Elle réagit plus vite qu'une sma de même longueur et lisse un peu moins. C'est le choix par défaut quand on veut suivre une tendance sans attendre.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — longueur de la moyenne ; le facteur de lissage vaut 2 / (period + 1).\n\nRenvoie : un nombre, ou null si values contient moins de « period » valeurs.\n\n```js\nconst rapide = ta.ema(market.series(\"close\", 100), 12);\nconst lente = ta.ema(market.series(\"close\", 100), 26);\n```\n\n### ta.wma(values, period)\n\nLa moyenne pondérée linéairement : la valeur la plus récente compte « period » fois, la précédente period − 1 fois, et ainsi de suite jusqu'à 1 pour la plus ancienne. Entre la sma et l'ema en réactivité, avec une pondération qu'on peut expliquer à quelqu'un sans parler d'exponentielle. Sert surtout de brique à hma.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — longueur de la fenêtre pondérée.\n\nRenvoie : un nombre, ou null si values contient moins de « period » valeurs.\n\n```js\nconst wma20 = ta.wma(market.series(\"close\", 60), 20);\n```\n\n### ta.hma(values, period)\n\nLa moyenne de Hull : wma(2 × wma(period / 2) − wma(period), √period). Cette construction annule l'essentiel du retard d'une moyenne mobile — elle tourne nettement plus tôt qu'une wma de même longueur tout en restant lisse. À utiliser quand le retard coûte cher et qu'un dépassement au retournement est acceptable.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — longueur nominale. La fenêtre réelle est plus longue : voir la mise en garde.\n\nRenvoie : un nombre, ou null tant que la fenêtre interne n'est pas remplie.\n\n```js\nconst hull = ta.hma(market.series(\"close\", 120), 21);\n```\n\nElle a besoin d'environ period + √period valeurs avant de renvoyer autre chose que null — demandez donc plus de barres à market.series que la période seule ne le suggère. Et elle dépasse : sur un retournement brutal, elle pointe au-delà du prix avant de revenir. C'est le prix de sa réactivité, pas un défaut de calcul.\n\n### ta.alma(values, period, offset?, sigma?)\n\nLa moyenne d'Arnaud Legoux : une fenêtre gaussienne dont on choisit où placer le sommet et à quelle vitesse le poids retombe de part et d'autre. C'est la seule des moyennes ici dont on règle explicitement le compromis réactivité / lissage, au lieu de le subir.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — longueur de la fenêtre.\n- offset — où se place le sommet de la cloche dans la fenêtre, de 0 à 1. 1 = sur la barre la plus récente (le plus réactif, le moins lisse), 0 = sur la plus ancienne. Défaut 0,85.\n- sigma — étroitesse de la cloche. Plus sigma est grand, plus la fenêtre est resserrée autour du sommet et plus la moyenne colle au prix. Défaut 6.\n\nRenvoie : un nombre, ou null si values contient moins de « period » valeurs.\n\n```js\n// Presque aussi réactive qu'un prix brut :\nconst reactive = ta.alma(market.series(\"close\", 80), 20, 0.99, 6);\n// Nettement plus lisse :\nconst lisse = ta.alma(market.series(\"close\", 80), 20, 0.5, 3);\n```\n\n### ta.swma(values)\n\nLa moyenne pondérée symétrique sur quatre barres, pondérées 1/6, 2/6, 2/6, 1/6. Sa fenêtre est fixe par définition — c'est un lissage court, standard, utilisé pour adoucir une série bruitée avant de la comparer à autre chose.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent. Au moins quatre valeurs.\n\nRenvoie : un nombre, ou null si values contient moins de quatre valeurs.\n\n```js\nconst adouci = ta.swma(market.series(\"close\", 10));\n```\n\nElle ne prend pas de période : la lui passer n'a aucun effet, la fenêtre reste de quatre barres.\n\n### ta.vwma(values, volumes, period)\n\nLa moyenne pondérée par le volume : chaque prix compte à proportion de ce qui s'est échangé dessus. Une barre calme la déplace peu, une barre active beaucoup. C'est la moyenne à utiliser quand on veut le prix « où le marché a réellement traité », pas le prix moyen affiché.\n\nParamètres :\n\n- values — les prix, du plus ancien au plus récent.\n- volumes — les volumes, alignés barre par barre sur values. Même longueur, même ordre.\n- period — longueur de la fenêtre.\n\nRenvoie : un nombre, ou null si l'une des deux séries est trop courte, ou si le volume total de la fenêtre est nul.\n\n```js\nconst prix = market.series(\"close\", 60);\nconst vol = market.series(\"volume\", 60);\nconst vwma20 = ta.vwma(prix, vol, 20);\n```\n\nLes deux tableaux doivent être alignés barre par barre. Deux appels séparés à market.series avec le même count le garantissent ; découper l'un des deux à la main ne le garantit plus.\n\n### ta.zlema(values, period)\n\nL'ema « à retard nul » : elle lisse 2 × prix − prix[il y a (period − 1) / 2 barres] plutôt que le prix lui-même. Cette soustraction compense d'avance le retard qu'une ema introduit, si bien qu'elle tourne plus tôt. Comme hma, elle dépasse au retournement.\n\nParamètres :\n\n- values — tableau de nombres, du plus ancien au plus récent.\n- period — longueur de l'ema sous-jacente ; le décalage compensé vaut (period − 1) / 2, arrondi.\n\nRenvoie : un nombre, ou null tant que la fenêtre, décalage compris, n'est pas remplie.\n\n```js\nconst zl = ta.zlema(market.series(\"close\", 100), 21);\n```\n\n### ta.rsi(values, period)\n\nL'indice de force relative : compare l'ampleur moyenne des hausses à celle des baisses sur la fenêtre, et la ramène sur une échelle de 0 à 100. Il mesure la vigueur d'un mouvement, pas sa direction — lu classiquement comme « suracheté » au-dessus de 70 et « survendu » en dessous de 30.\n\nParamètres :\n\n- values — les prix, du plus ancien au plus récent.\n- period — longueur de la fenêtre. 14 est la valeur usuelle.\n\nRenvoie : un nombre entre 0 et 100, ou null si values contient moins de period + 1 valeurs.\n\n```js\nconst rsi = ta.rsi(market.series(\"close\", 60), 14);\nif (rsi !== null && rsi > 70) alert(\"suracheté\");\n```\n\nUn RSI extrême n'est pas un signal de retournement : dans une tendance forte il peut rester au-dessus de 70 pendant des semaines. Il dit qu'un mouvement est vigoureux, pas qu'il est fini.\n\n### ta.roc(values, period)\n\nLe taux de variation : de combien de pour cent la valeur a bougé depuis « period » barres. La mesure de momentum la plus directe qui soit, sans lissage et sans échelle bornée.\n\nParamètres :\n\n- values — les prix, du plus ancien au plus récent.\n- period — l'écart, en barres, avec lequel comparer.\n\nRenvoie : un nombre en pourcentage (5 pour +5 %), ou null si values est trop court.\n\n```js\nconst perf20 = ta.roc(market.series(\"close\", 40), 20);\n```\n\n### ta.atr(high, low, close, period)\n\nL'Average True Range : l'amplitude moyenne réelle d'une barre, gaps compris. Ce n'est pas un indicateur de direction mais de volatilité — c'est l'outil pour dimensionner un stop ou une position en unités de marché plutôt qu'en pourcentage arbitraire.\n\nParamètres :\n\n- high — les plus hauts, du plus ancien au plus récent.\n- low — les plus bas, alignés sur high.\n- close — les clôtures, alignées sur high.\n- period — longueur du lissage. 14 est la valeur usuelle.\n\nRenvoie : un nombre exprimé dans l'unité de prix de l'instrument, ou null si les séries sont trop courtes.\n\n```js\nconst n = 60;\nconst atr = ta.atr(market.series(\"high\", n), market.series(\"low\", n), market.series(\"close\", n), 14);\n// Un stop à deux ATR sous le prix, quelle que soit la volatilité du moment :\nconst stop = atr === null ? null : market.close(0) - 2 * atr;\n```\n\nLes trois séries doivent avoir la même longueur et être alignées barre par barre.\n\n### ta.macd(values, fastPeriod?, slowPeriod?, signalPeriod?)\n\nLa convergence-divergence de moyennes mobiles : la différence entre une ema rapide et une ema lente, sa propre moyenne (la ligne de signal), et l'écart entre les deux (l'histogramme). Il lit un changement de régime de tendance — le croisement des deux lignes est le signal classique, le passage de l'histogramme par zéro en est la même information.\n\nParamètres :\n\n- values — les prix, du plus ancien au plus récent.\n- fastPeriod — longueur de l'ema rapide. Défaut 12.\n- slowPeriod — longueur de l'ema lente. Défaut 26.\n- signalPeriod — longueur de la moyenne appliquée à la différence. Défaut 9.\n\nRenvoie : un objet { macd, signal, histogram } — macd est un nombre, signal et histogram peuvent être null tant que la moyenne de signal n'a pas assez de valeurs. L'objet entier vaut null si values est trop court.\n\n```js\nconst m = ta.macd(market.series(\"close\", 120));\nif (m !== null && m.histogram !== null && m.histogram > 0) plot.signal(\"haussier\");\n```\n\n### ta.bollinger(values, period?, stdDev?)\n\nLes bandes de Bollinger : une moyenne mobile et deux bornes placées à N écarts-types de part et d'autre. Elles s'écartent quand le marché s'agite et se resserrent quand il se calme, ce qui en fait autant une mesure de volatilité qu'un repère de niveau.\n\nParamètres :\n\n- values — les prix, du plus ancien au plus récent.\n- period — longueur de la moyenne et de l'écart-type. Défaut 20.\n- stdDev — nombre d'écarts-types entre la moyenne et chaque bande. Défaut 2.\n\nRenvoie : un objet { upper, middle, lower } de trois nombres, ou null si values contient moins de « period » valeurs.\n\n```js\nconst b = ta.bollinger(market.series(\"close\", 60), 20, 2);\nif (b !== null) plot.overlay(\"Bollinger\").band(\"BB\", b.upper, b.lower);\n```\n\nToucher une bande n'est pas un signal en soi : en tendance, le prix « marche » le long de la bande supérieure pendant longtemps. C'est le resserrement, puis l'expansion, qui portent l'information.\n\n### ta.stochastic(high, low, close, period?, signalPeriod?)\n\nL'oscillateur stochastique : où se situe la clôture dans l'amplitude haut-bas de la fenêtre, de 0 à 100, plus une moyenne de cette lecture. Il répond à « clôture-t-on en haut ou en bas de la récente fourchette » — utile en marché sans direction, trompeur en tendance.\n\nParamètres :\n\n- high — les plus hauts, du plus ancien au plus récent.\n- low — les plus bas, alignés sur high.\n- close — les clôtures, alignées sur high.\n- period — longueur de la fenêtre haut-bas. Défaut 14.\n- signalPeriod — longueur de la moyenne appliquée à %K pour obtenir %D. Défaut 3.\n\nRenvoie : un objet { k, d } — k est la lecture brute, d sa moyenne. null si les séries sont trop courtes.\n\n```js\nconst n = 60;\nconst st = ta.stochastic(market.series(\"high\", n), market.series(\"low\", n), market.series(\"close\", n));\nif (st !== null && st.k < 20 && st.k > st.d) plot.signal(\"achat\");\n```\n\n### ta.adx(high, low, close, period?)\n\nL'indice directionnel moyen, avec ses deux composantes. adx mesure la FORCE d'une tendance sans dire son sens (au-dessus de 25, on considère qu'il y a tendance ; en dessous de 20, que le marché va de côté). plusDI et minusDI disent le sens : lequel des deux domine. C'est l'outil pour n'appliquer une stratégie de suivi que quand il y a réellement quelque chose à suivre.\n\nParamètres :\n\n- high — les plus hauts, du plus ancien au plus récent.\n- low — les plus bas, alignés sur high.\n- close — les clôtures, alignées sur high.\n- period — longueur du lissage. Défaut 14.\n\nRenvoie : un objet { adx, plusDI, minusDI } de trois nombres, ou null si les séries sont trop courtes.\n\n```js\nconst n = 80;\nconst a = ta.adx(market.series(\"high\", n), market.series(\"low\", n), market.series(\"close\", n));\n// Ne suivre la tendance que lorsqu'il y en a une :\nif (a !== null && a.adx > 25 && a.plusDI > a.minusDI) strategy.long(\"tendance haussière établie\");\n```\n\nadx a besoin d'environ deux fois la période pour se stabiliser : demandez large à market.series.\n\n## console.log\n\nconsole.log(...) fonctionne normalement et s'affiche dans la console de l'éditeur, sous le graphique — pratique pour déboguer un script pendant son écriture. Les autres méthodes de console ne sont pas capturées.\n\n## Sécurité et limites\n\n- Aucun accès réseau — fetch, XMLHttpRequest, WebSocket, importScripts et navigator.sendBeacon sont bloqués et lèvent une erreur explicite si un script tente de les appeler.\n- Aucun accès au stockage du navigateur — indexedDB et l'API Cache sont bloqués de la même façon.\n- Aucun sous-Worker — un script ne peut pas créer son propre Worker (ce qui aurait été un moyen de contourner les restrictions ci-dessus).\n- Ni eval ni Function — les deux autres routes vers du code qui n'apparaît nulle part dans le texte du script sont bloquées elles aussi.\n- Aucun accès aux variables ou au code de l'application hôte — le script ne reçoit que les API documentées ici, rien d'autre.\n- Délai d'exécution — 8 secondes pour un rejeu complet, 1,5 seconde pour un tick temps réel ; au-delà, l'exécution est interrompue de force.\n- market.series() est plafonné à 5000 points, quelle que soit la longueur demandée.\n- plot.xy() et pane.profile() sont plafonnés à 2000 points chacun — au-delà, tronqués silencieusement plutôt que rejetés.\n- plot.table() est plafonné à 50 lignes et 200 caractères par cellule — au-delà, tronqué silencieusement plutôt que rejeté.\n- L'anti-rafale des ticks en direct (DEBOUNCE_MS, voir plus haut) est de 300 ms par défaut pour tout script qui ne le déclare pas.\n\nMath, Date, JSON, Array, Map et Set restent pleinement utilisables — ce sont des briques de calcul pures, sans risque.\n\n### Erreurs courantes\n\nCe que l'éditeur affiche exactement quand quelque chose ne va pas, pour reconnaître chaque cas :\n\n- « Le script a dépassé le délai d'exécution autorisé et a été arrêté. » — le script est trop lent (une boucle qui tourne trop longtemps, un calcul lourd relancé à chaque bougie), pas une erreur de syntaxe. Voir les délais ci-dessus.\n- « \"fetch\" n'est pas accessible depuis un script. » (ou XMLHttpRequest/WebSocket/importScripts/Worker/indexedDB/caches/Notification/postMessage/Function/eval selon ce qui a été appelé) — une des restrictions de sécurité ci-dessus, pas un bug du script.\n- Une erreur de syntaxe (avant même la première exécution) n'a jamais de numéro de ligne, sur aucun moteur — seul le message est disponible pour celle-là.\n- Sous Safari/WebKit, aucune erreur survenant *pendant* l'exécution n'indique de numéro de ligne non plus, quelle que soit l'erreur — seul le message l'est. Chrome et Firefox en fournissent un dans la plupart des cas.\n\n## Exemples\n\n---\n\n# Scripts d'exemple complets et fonctionnels\n\nChacun s'exécute tel quel. Ce sont les modèles à imiter — pour le style, le découpage en @block et l'usage de l'API.\n\n## Rapport @report — analyse fondamentale d'une entreprise\n```js\n@report\n@description \"Analyse fondamentale : croissance, rentabilité,investissement, avantage concurrentiel.\"\n\n// Quatre exercices, lus en remontant. company.value(champ, décalage) renvoie ce que l'entreprise\n// avait publié il y a N bougies — les décalages se déduisent donc de l'historique réellement\n// disponible, jamais d'un « 252 séances = un an » qui tombe dans le vide dès que la chart est plus\n// courte que ce qu'on suppose.\nconst historique = market.series(\"close\").length;\nconst exercices = [0, 1, 2, 3];\nconst decalage = (i) => Math.floor((historique - 1) * ((3 - i) / 4));\nconst lire = (champ, i) => company.value(champ, decalage(i));\nconst md = (v) => (v === null ? null : +(v / 1e9).toFixed(2));\nconst pct = (v) => (v === null ? null : v.toFixed(1) + \" %\");\n\nreport.title(\"Analyse fondamentale\", { subtitle: \"Quatre exercices\", symbol: market.symbol() });\n\n// --- Chiffres clés : ce qu'on regarde avant de lire quoi que ce soit ---\nconst caN = lire(\"totalRevenue\", 3);\nconst caDebut = lire(\"totalRevenue\", 0);\nconst croissance = caDebut ? ((caN / caDebut) ** (1 / 3) - 1) * 100 : null;\nreport.metrics([\n  { label: \"Chiffre d'affaires\", value: md(caN) + \" Md\", tone: \"up\" },\n  { label: \"Croissance annualisée\", value: croissance === null ? \"—\" : pct(croissance), tone: croissance > 0 ? \"up\" : \"down\" },\n  { label: \"Marge nette\", value: pct(lire(\"netMargin\", 3)) },\n  { label: \"ROIC\", value: pct(lire(\"returnOnInvestedCapital\", 3)), note: \"vs \" + pct(lire(\"returnOnInvestedCapital\", 0)) + \" il y a 4 ans\" },\n]);\n\n// --- Compte de résultat ---\nreport.heading(\"Compte de résultat\");\nreport.table(\n  [\"Exercice\", \"CA\", \"Résultat net\", \"Marge nette\", \"Impôt\", \"Taux effectif\"],\n  exercices.map((i) => [\n    \"N-\" + (3 - i),\n    md(lire(\"totalRevenue\", i)),\n    md(lire(\"netIncome\", i)),\n    pct(lire(\"netMargin\", i)),\n    md(lire(\"taxExpense\", i)),\n    pct(lire(\"effectiveTaxRate\", i)),\n  ]),\n  { title: \"En milliards, sauf pourcentages\" }\n);\n\n// --- Investissement et trésorerie ---\nreport.heading(\"Investissement et trésorerie\");\nreport.text(\n  \"Le CAPEX dit ce qu'il en coûte de maintenir la position ; le flux de trésorerie disponible dit ce qu'il en reste.\"\n);\nconst etiquettes = exercices.map((i) => \"N-\" + (3 - i));\nreport.series(\"CAPEX\", etiquettes, exercices.map((i) => md(lire(\"capex\", i))), { unit: \"Md\" });\nreport.series(\n  \"Flux de trésorerie disponible\",\n  etiquettes,\n  exercices.map((i) => {\n    const flux = lire(\"operatingCashFlow\", i);\n    const capex = lire(\"capex\", i);\n    return flux === null || capex === null ? null : md(flux - capex);\n  }),\n  { unit: \"Md\" }\n);\n\n// --- Avantage concurrentiel ---\nreport.heading(\"Avantage concurrentiel\");\nconst roic = lire(\"returnOnInvestedCapital\", 3);\nconst roicDebut = lire(\"returnOnInvestedCapital\", 0);\nreport.text(\n  roic === null\n    ? \"L'application n'a pas fourni de ROIC : impossible de conclure sur la rentabilité du capital investi.\"\n    : \"Le ROIC s'établit à \" + pct(roic) + \", contre \" + pct(roicDebut) + \" il y a quatre exercices.\"\n);\nif (roic !== null && roic > 15) {\n  report.callout(\n    \"positive\",\n    \"Rentabilité durablement élevée\",\n    \"Un ROIC maintenu au-dessus de 15 % sur plusieurs exercices consécutifs s'explique rarement par la conjoncture : c'est le signe d'une barrière à l'entrée. Reste à nommer laquelle.\"\n  );\n} else if (roic !== null) {\n  report.callout(\n    \"neutral\",\n    \"Rentabilité ordinaire\",\n    \"Rien ici n'indique un avantage concurrentiel durable : le capital investi rapporte ce que rapporte le capital investi.\"\n  );\n}\n\nreport.heading(\"Champs disponibles\");\nreport.text(\"Données fournies par l'application : \" + company.fields().join(\", \") + \".\");\n```\n\n## Analyse @quant — comparer plusieurs symboles\n```js\n@quant(AAPL, MSFT, NVDA)\n@description \"Comparaison transversale : performance, volatilité, distance au plus haut.\"\n\n// Une analyse @quant tourne UNE fois par symbole, positionnée sur la dernière bougie — market.*\n// voit donc tout l'historique. Aucun plot n'est disponible ici : le résultat, c'est le return.\nconst closes = market.series(\"close\", 260);\nif (closes.length < 30) return { erreur: \"Historique trop court\" };\n\nconst last = closes[closes.length - 1];\nconst perf = (barres) => {\n  const past = closes[closes.length - 1 - barres];\n  return past === undefined || past === 0 ? null : +(((last - past) / past) * 100).toFixed(2);\n};\n\n// Volatilité annualisée à partir des rendements quotidiens, en supposant 252 séances.\nconst rendements = [];\nfor (let i = 1; i < closes.length; i++) {\n  if (closes[i - 1] !== 0) rendements.push(closes[i] / closes[i - 1] - 1);\n}\nconst moyenne = rendements.reduce((a, b) => a + b, 0) / rendements.length;\nconst variance = rendements.reduce((a, r) => a + (r - moyenne) ** 2, 0) / rendements.length;\nconst volatilite = +(Math.sqrt(variance) * Math.sqrt(252) * 100).toFixed(2);\n\nconst plusHaut = Math.max(...closes);\n\nreturn {\n  cours: +last.toFixed(2),\n  \"perf 1M\": perf(21),\n  \"perf 3M\": perf(63),\n  \"perf 1A\": perf(252),\n  \"volatilité\": volatilite,\n  \"sous le plus haut\": +(((last - plusHaut) / plusHaut) * 100).toFixed(2),\n};\n```\n\n## Quant Score — RSI + MACD + moyenne mobile\n```js\n@indicator\n// Lit un RSI et un MACD déjà présents sur la chart plutôt que de les recalculer ici —\n// voir \"Indicateurs disponibles\" dans l'éditeur pour les identifiants réels de votre chart.\nconst rsi = chart.indicator(\"rsi\").value(0);\nconst macdHist = chart.indicator(\"macd\").histogram(0);\nconst price = market.close(0);\nconst sma20 = math.sma(market.series(\"close\", 20), 20);\n\n// Un point par condition remplie : 0 à 3, jamais négatif.\nlet score = 0;\nif (rsi !== null && rsi > 50) score += 1;          // momentum haussier\nif (macdHist !== null && macdHist > 0) score += 1; // MACD au-dessus de son signal\nif (sma20 !== null && price > sma20) score += 1;   // prix au-dessus de sa moyenne 20\n\n// Le score dans son propre panneau, la moyenne mobile superposée au prix.\nplot.pane(\"Quant Score\").line(\"Quant Score\", score);\nplot.overlay(\"SMA 20\").line(\"SMA 20\", sma20 ?? price);\n\n// Un seul signal par bougie (bar.isNew()), uniquement quand les trois conditions sont réunies.\nif (bar.isNew() && score === 3) {\n  plot.signal(\"BUY\");\n  alert(\"Quant Score au maximum (3/3)\");\n}\n```\n\n## Croisement de moyennes mobiles (Golden / Death Cross)\n```js\n@indicator\nconst shortMA = math.sma(market.series(\"close\", 50), 50);\nconst longMA = math.sma(market.series(\"close\", 200), 200);\n// La valeur des deux moyennes à la bougie PRÉCÉDENTE — nécessaire pour détecter le moment exact\n// du croisement (avant/après), pas juste \"laquelle est au-dessus en ce moment\".\nconst prevShort = state.get(\"prevShort\", null);\nconst prevLong = state.get(\"prevLong\", null);\n\nplot.overlay(\"SMA 50\").line(\"SMA 50\", shortMA ?? market.close(0));\nplot.overlay(\"SMA 200\").line(\"SMA 200\", longMA ?? market.close(0));\n\n// Croisement = la courte était en dessous (ou égale) avant, et est au-dessus maintenant (ou l'inverse).\nif (bar.isNew() && prevShort !== null && prevLong !== null && shortMA !== null && longMA !== null) {\n  if (prevShort <= prevLong && shortMA > longMA) {\n    plot.signal(\"BUY\");\n    alert(\"Golden Cross : SMA 50 croise SMA 200 à la hausse\");\n  }\n  if (prevShort >= prevLong && shortMA < longMA) {\n    plot.signal(\"SELL\");\n    alert(\"Death Cross : SMA 50 croise SMA 200 à la baisse\");\n  }\n}\n\n// Mémorise la valeur de cette bougie pour que la PROCHAINE puisse à son tour la lire comme \"prev*\".\nstate.set(\"prevShort\", shortMA);\nstate.set(\"prevLong\", longMA);\n```\n\n## Rupture des bandes de Bollinger\n```js\n@indicator\n// Calculé \"à la volée\" via ta.* — pas besoin d'avoir ajouté de Bollinger à la chart.\nconst bb = ta.bollinger(market.series(\"close\", 60), 20, 2);\nconst price = market.close(0);\n\n// null tant qu'il n'y a pas encore 20 clôtures d'historique (période de chauffe) — on ne trace\n// et ne signale rien avant que le calcul ait un sens.\nif (bb) {\n  plot.overlay(\"Bollinger\").band(\"Bollinger\", bb.upper, bb.lower);\n\n  // Rupture = clôture strictement au-delà d'une des deux bandes.\n  if (bar.isNew() && price > bb.upper) {\n    plot.signal(\"SELL\");\n    alert(\"Prix au-dessus de la bande de Bollinger supérieure\");\n  }\n  if (bar.isNew() && price < bb.lower) {\n    plot.signal(\"BUY\");\n    alert(\"Prix en dessous de la bande de Bollinger inférieure\");\n  }\n}\n```\n\n## Détecteur de pic de volume\n```js\n@indicator\nconst volumes = market.series(\"volume\", 20);\nconst avgVolume = math.mean(volumes);\nconst stdVolume = math.std(volumes);\nconst currentVolume = market.volume(0);\n\n// Seuil statistique plutôt qu'un chiffre fixe : \"anormalement haut\" dépend de l'instrument\n// (un volume de 1M peut être énorme pour l'un, minuscule pour un autre).\nif (bar.isNew() && avgVolume !== null && stdVolume !== null && currentVolume !== null) {\n  if (currentVolume > avgVolume + 2 * stdVolume) {\n    plot.point(market.close(0), { color: \"#e8391c\", shape: \"pin\" });\n    alert(\"Pic de volume détecté (> moyenne + 2 écarts-types)\");\n  }\n}\n```\n\n## Score de momentum (RSI + Stochastique)\n```js\n@indicator\nconst closes = market.series(\"close\", 60);\nconst highs = market.series(\"high\", 60);\nconst lows = market.series(\"low\", 60);\n\nconst rsi = ta.rsi(closes, 14);\nconst stoch = ta.stochastic(highs, lows, closes, 14, 3);\n\n// Même principe de score que le Quant Score plus haut, mais avec deux indicateurs différents —\n// preuve que le score composite n'est pas lié à une combinaison précise d'indicateurs.\nlet score = 0;\nif (rsi !== null && rsi > 55) score += 1;                  // RSI franchement au-dessus du milieu\nif (stoch !== null && stoch.k > stoch.d) score += 1;        // %K au-dessus de sa ligne de signal\nif (stoch !== null && stoch.k < 80) score += 1;             // évite la zone de surachat extrême\n\nplot.pane(\"Momentum Score\").line(\"Momentum Score\", score);\n\nif (bar.isNew() && score === 3) {\n  alert(\"Score de momentum au maximum (3/3)\");\n}\n```\n\n## Canal de rupture\n```js\n@indicator\nconst period = 20;\n// Le plus haut plus haut et le plus bas plus bas des 20 dernières bougies — le canal lui-même.\nconst upperChannel = math.max(market.series(\"high\", period));\nconst lowerChannel = math.min(market.series(\"low\", period));\nconst price = market.close(0);\n\nplot.overlay(\"Canal\").band(\"Canal\", upperChannel ?? price, lowerChannel ?? price);\n\n// Rupture = clôture qui égale ou dépasse une borne du canal (>= / <=, pas > / < : toucher la\n// borne compte déjà comme une rupture, pas seulement la dépasser).\nif (bar.isNew() && upperChannel !== null && price >= upperChannel) {\n  plot.signal(\"BUY\");\n  alert(\"Rupture du canal des \" + period + \" dernières bougies (plus haut)\");\n}\nif (bar.isNew() && lowerChannel !== null && price <= lowerChannel) {\n  plot.signal(\"SELL\");\n  alert(\"Rupture du canal des \" + period + \" dernières bougies (plus bas)\");\n}\n```\n\n## Pane ancrée à droite (squelette)\n```js\n@indicator\n// La pane est créée par son nom au premier appel, puis retrouvée par ce même nom à chaque bougie\n// — \"le dernier appel gagne\" pour chaque série qu'elle contient.\nconst droite = plot.pane(\"Ma pane\", { dock: \"right\" });\n\n// Une pane vide ne s'affiche pas : il lui faut au moins une série. Le prix de clôture fait un\n// contenu de remplacement honnête, à remplacer par ce que vous voulez vraiment y voir.\ndroite.line(\"Clôture\", market.close(0) ?? 0);\n```\n\n## Trend Indicator A (v2.3) — portage Pine Script\n```js\n@indicator\n@description \"///Trend Indicator A (v2.3)///\nPortage fidèle de l'indicateur de **DZIV** (CC BY-NC-SA 4.0). L'idée tient en une phrase : lisser\nles quatre séries **Heikin-Ashi** avec la même moyenne mobile, puis lire la bougie moyenne qui en\nrésulte.\n\n//Pourquoi Heikin-Ashi//\nUne bougie Heikin-Ashi est déjà une moyenne — son ouverture est la moyenne de l'ouverture et de la\nclôture précédentes. Lisser ces quatre séries plutôt que les prix bruts enlève le bruit deux fois,\net ce qui reste est la --direction-- du marché plutôt que ses à-coups.\n\n//Ce qui est tracé//\nLa ligne de __clôture lissée__, **verte quand le corps de la bougie moyenne est haussier**, rouge\nsinon. Entre l'ouverture et la clôture lissées, un nuage de la même couleur : son épaisseur est la\nconviction. Les mèches (haut et bas lissés) ferment deux nuages gris très pâles, qui disent\njusqu'où le marché est allé sans y rester.\"\n\n@block Cellule 1 — les réglages\n// Tous les réglages de l'original, déclarés en Variable : ils apparaissent dans le panneau\n// « Paramètres » et se changent sans toucher au code.\nconst TYPE_MM = new Variable(\"string\", \"EMA\", {\n  description: \"Type de moyenne mobile : ALMA, HMA, SMA, SWMA, VWMA, WMA, ZLEMA ou EMA.\",\n});\nconst PERIODE = new Variable(\"number\", 9, { description: \"Longueur de la moyenne mobile.\", min: 1, max: 200 });\nconst ALMA_DECALAGE = new Variable(\"number\", 0.85, { description: \"ALMA uniquement — position du pic de la fenêtre gaussienne (0 = le plus ancien, 1 = le plus récent).\", min: 0, max: 1 });\nconst ALMA_SIGMA = new Variable(\"number\", 6, { description: \"ALMA uniquement — netteté du pic. Plus grand = suit le prix de plus près.\", min: 1, max: 20 });\nconst AFFICHER_MECHES = new Variable(\"boolean\", false, { description: \"Trace aussi les lignes du haut et du bas lissés.\" });\nconst AFFICHER_NUAGES = new Variable(\"boolean\", true, { description: \"Remplit les nuages entre les mèches et le corps.\" });\nconst COULEUR_HAUSSE = new Variable(\"color\", \"#26a69a\", { description: \"Couleur quand le corps de la bougie moyenne est haussier.\" });\nconst COULEUR_BAISSE = new Variable(\"color\", \"#ef5350\", { description: \"Couleur quand il est baissier.\" });\nconst COULEUR_NEUTRE = new Variable(\"color\", \"#808080\", { description: \"Couleur des mèches et de leurs nuages.\" });\n\n@block Cellule 2 — les quatre séries Heikin-Ashi, lissées\n// market.heikinAshi() rend les quatre séries d'un coup, les plus anciennes en premier. Ce n'est\n// pas quelque chose qu'un script peut recalculer lui-même : l'ouverture HA dépend de la bougie\n// HA précédente, donc de toutes celles d'avant — voir sa doc.\nconst FENETRE = Math.max(60, PERIODE * 4);\nconst ha = market.heikinAshi(FENETRE);\nconst volumes = market.series(\"volume\", FENETRE);\n\n// Le switch de l'original. Une seule fonction appliquée aux quatre séries, exactement comme f(x).\nfunction moyenne(valeurs) {\n  switch (TYPE_MM.toUpperCase()) {\n    case \"ALMA\": return ta.alma(valeurs, PERIODE, ALMA_DECALAGE, ALMA_SIGMA);\n    case \"HMA\": return ta.hma(valeurs, PERIODE);\n    case \"SMA\": return ta.sma(valeurs, PERIODE);\n    case \"SWMA\": return ta.swma(valeurs);\n    case \"VWMA\": return ta.vwma(valeurs, volumes, PERIODE);\n    // L'original écrit ici `ta.vwma(x, ma_period)` — un copier-coller depuis la ligne VWMA\n    // juste au-dessus, qui fait que « WMA » calcule en réalité une VWMA. On corrige : une WMA\n    // pondère par l'ancienneté, pas par le volume.\n    case \"WMA\": return ta.wma(valeurs, PERIODE);\n    case \"ZLEMA\": return ta.zlema(valeurs, PERIODE);\n    default: return ta.ema(valeurs, PERIODE);\n  }\n}\n\nconst mmOuverture = moyenne(ha.open);\nconst mmCloture = moyenne(ha.close);\nconst mmHaut = moyenne(ha.high);\nconst mmBas = moyenne(ha.low);\n\n@block Cellule 3 — la tendance\n// trend = 100 × (clôture − ouverture) / (haut − bas) : la part du chemin parcouru sur la bougie\n// moyenne qui l'a été dans le sens du corps. Seul son signe sert au tracé, mais la valeur elle-\n// même se lit comme une force, d'où le panneau séparé plus bas.\nconst amplitude = mmHaut !== null && mmBas !== null ? mmHaut - mmBas : null;\nconst tendance =\n  mmCloture !== null && mmOuverture !== null && amplitude !== null && amplitude !== 0\n    ? (100 * (mmCloture - mmOuverture)) / amplitude\n    : null;\nconst haussier = tendance !== null && tendance > 0;\n\n@block Cellule 4 — le tracé\n// Deux séries pour une seule courbe : la couleur d'une série est fixée à sa première valeur et ne\n// change plus ensuite. Une courbe bicolore se fait donc avec deux séries, chacune à null là où\n// l'autre s'affiche — sans le null, la série relierait ses points par-dessus le trou.\nconst prix = plot.overlay(\"Trend Indicator A\");\nprix.line(\"Clôture lissée (hausse)\", haussier ? mmCloture : null, { color: COULEUR_HAUSSE, lineWidth: 2 });\nprix.line(\"Clôture lissée (baisse)\", haussier ? null : mmCloture, { color: COULEUR_BAISSE, lineWidth: 2 });\n\n// Le nuage entre ouverture et clôture, en deux séries pour la même raison que la courbe.\n//\n// Et surtout : les deux sont émises à *chaque* bougie, celle qui ne s'applique pas recevant null.\n// Ne rien émettre du tout n'est pas la même chose — une série sans valeur sur une bougie prolonge\n// sa dernière, ce qui donnait de longs paliers horizontaux là où la couleur changeait. null est\n// ce qui perce un trou.\nprix.band(\"Corps (hausse)\", haussier ? mmCloture : null, haussier ? mmOuverture : null, { color: COULEUR_HAUSSE, lineWidth: 0 });\nprix.band(\"Corps (baisse)\", haussier ? null : mmCloture, haussier ? null : mmOuverture, { color: COULEUR_BAISSE, lineWidth: 0 });\n\n// Même règle ici : la valeur est null quand l'option est éteinte, jamais l'appel qui disparaît.\nprix.line(\"Haut lissé\", AFFICHER_MECHES ? mmHaut : null, { color: COULEUR_NEUTRE });\nprix.line(\"Bas lissé\", AFFICHER_MECHES ? mmBas : null, { color: COULEUR_NEUTRE });\n\n// Deux nuages très pâles : du haut jusqu'au sommet du corps, et du bas du corps jusqu'au bas.\n// Ils disent jusqu'où le marché est allé sans y rester.\nconst corpsHaut = mmOuverture !== null && mmCloture !== null ? Math.max(mmOuverture, mmCloture) : null;\nconst corpsBas = mmOuverture !== null && mmCloture !== null ? Math.min(mmOuverture, mmCloture) : null;\nprix.band(\"Mèche haute\", AFFICHER_NUAGES ? mmHaut : null, AFFICHER_NUAGES ? corpsHaut : null, { color: COULEUR_NEUTRE, lineWidth: 0 });\nprix.band(\"Mèche basse\", AFFICHER_NUAGES ? corpsBas : null, AFFICHER_NUAGES ? mmBas : null, { color: COULEUR_NEUTRE, lineWidth: 0 });\n\n@block Cellule 5 — la force, dans son propre panneau\n// Absent de l'original, qui n'affiche que la couleur. La valeur de `trend` est une échelle de\n// -100 à +100 qui se lit bien seule : au-delà de ±50, le corps de la bougie moyenne occupe plus\n// de la moitié de son amplitude, ce qui est une tendance franche.\nplot.pane(\"Force de tendance\").histogram(\"Force\", tendance, { color: haussier ? COULEUR_HAUSSE : COULEUR_BAISSE });\n```\n\n## Niveaux de support/résistance (KDE gaussienne)\n```js\n@indicator\n@description \"///Niveaux de support/résistance///\nUn **profil de marché** lissé par un noyau gaussien. Plutôt que de compter combien de fois le prix\na visité chaque palier, chaque clôture est étalée en une petite cloche, et toutes les cloches sont\nadditionnées : le profil obtenu est *continu* au lieu d'être en escalier.\n\n//Pourquoi en log-prix//\nTout le calcul se fait sur le --logarithme-- des clôtures, pas sur les prix eux-mêmes. Un noyau de\nlargeur fixe en euros est trop large en bas de l'échelle et trop étroit en haut ; en log, une même\nlargeur vaut le même **pourcentage** de mouvement partout, ce qui est la bonne façon de comparer\ndes zones de prix éloignées. La grille est reconvertie en prix (exp) au dernier moment.\n\n//Ce que le script affiche//\nLe profil est dessiné dans la pane de droite, **tourné d'un quart de tour** : les prix en vertical,\nalignés sur ceux du graphe principal, et la densité qui s'étend horizontalement. Chaque bosse est\ndonc à la hauteur exacte du prix qu'elle désigne.\n\nLes pics de ce profil sont les niveaux de __support et de résistance__. Chacun est ramené sur les\nbougies sous forme d'un **semis de points**, à la hauteur exacte de la bosse qui l'a produit — un\npoint par bougie, qui s'interrompt dès que le niveau cesse d'être détecté. Une flèche BUY/SELL se\npose en plus dès qu'une clôture en franchit un.\n\n//Les réglages qui comptent//\n**ATR_MULT** élargit ou resserre les cloches : plus haut, moins de niveaux, mais plus robustes.\n\n**PROM_THRESH** écarte les pics trop plats.\n\n**RECALC_EVERY** espace les recalculs — le profil complet coûte cher, et les niveaux ne bougent\n--pratiquement jamais-- d'une bougie à l'autre.\n\n**AFFICHER_NIVEAUX** masque les points si seul le profil de droite vous intéresse.\n\"\n\n@block Cellule 1 — paramètres réglables et outils de calcul\n// new Variable(type, défaut, { description }) expose la constante dans la fenêtre de réglages :\n// on peut la régler sans rouvrir le code, et le script se relance tout seul à chaque changement.\n// La description s'affiche sous le champ correspondant.\nconst WINDOW = new Variable(\"number\", 500, {\n  description:\n    \"Nombre de bougies (les plus récentes) utilisées pour construire le profil. Le projet de référence calcule sur toute la fenêtre visible du graphe ; ici, où le script s'exécute bougie par bougie, c'est cette fenêtre glissante qui en tient lieu — plus elle est large, plus le profil est stable, et plus il coûte cher.\",\n  min: 10,\n});\nconst GRID = new Variable(\"number\", 200, {\n  description:\n    \"Nombre de niveaux de prix échantillonnés entre le plus bas et le plus haut de la fenêtre (le numPoints de la référence). C'est le réglage qui pèse le plus sur la finesse du profil : bas (quelques dizaines) donne un profil grossier à peu de pics larges, haut (deux cents et plus) un profil fin capable de distinguer des pics rapprochés.\",\n  min: 5,\n});\nconst FIRST_W = new Variable(\"number\", 0.01, {\n  description:\n    \"Poids de la bougie la plus ancienne de la fenêtre par rapport à la plus récente (qui vaut 1). Plus bas = le profil privilégie les prix récents.\",\n  min: 0,\n  max: 1,\n});\nconst ATR_MULT = new Variable(\"number\", 3, {\n  description:\n    \"Largeur du noyau gaussien, exprimée comme le bw_method scalaire de scipy.gaussian_kde : la largeur finale vaut ATR_MULT × ATR-log moyen × écart-type pondéré des log-clôtures. Bas = noyaux étroits, profil détaillé à beaucoup de pics ; haut = noyaux larges, profil lissé à peu de pics mais plus robustes.\",\n  min: 0.05,\n});\nconst PROM_THRESH = new Variable(\"number\", 0.25, {\n  description:\n    \"Hauteur minimale qu'un pic doit dépasser au-dessus de ses vallées voisines pour devenir un niveau, en fraction du pic le plus haut du profil. Bas = plus de niveaux détectés, y compris des pics mineurs ; haut = seuls les pics les plus marqués sont gardés.\",\n  min: 0,\n  max: 1,\n});\nconst RECALC_EVERY = new Variable(\"number\", 5, {\n  description:\n    \"Ne recalculer le profil qu'une bougie sur N ; entre deux recalculs, le dernier profil obtenu est réutilisé tel quel. 1 = recalcul à chaque bougie.\\n\\nPourquoi l'éviter : le script est réexécuté une fois par bougie sur tout l'historique, et un recalcul complet visite chacun des GRID niveaux de prix pour chacune des WINDOW clôtures de la fenêtre — 200 × 500 = 100 000 calculs avec les réglages par défaut. Sur un historique de ~3000 bougies, cela fait ~2,7 s à N=1 contre ~0,4 s à N=5, là où le moteur interrompt un rejeu au-delà de 8 s et une mise à jour en direct au-delà de 1,5 s.\\n\\nCe qu'on perd en montant N : presque rien. Les niveaux ne bougent pratiquement pas d'une bougie à l'autre, et le profil affiché est de toute façon le dernier calculé.\",\n  min: 1,\n});\nconst PROFIL_COULEUR = new Variable(\"color\", \"#c47f2a\", { description: \"Couleur de la courbe du profil affichée dans la pane de droite.\" });\nconst PROFIL_MARGE = new Variable(\"number\", 0.08, {\n  description:\n    \"Espace laissé entre le pic le plus haut du profil et la barre de séparation verticale de la pane, en fraction de la largeur de la colonne. 0 = la courbe touche la barre.\",\n  min: 0,\n  max: 0.5,\n});\nconst AFFICHER_FLECHES = new Variable(\"boolean\", false, { description: \"Affiche les flèches BUY/SELL sur le graphique quand un niveau est franchi.\" });\nconst AFFICHER_NIVEAUX = new Variable(\"boolean\", true, {\n  description: \"Trace chaque niveau détecté en ligne horizontale sur le graphique des prix, en face de la bosse du profil qui l'a produit.\",\n});\nconst COULEUR_NIVEAUX = new Variable(\"color\", \"#c47f2a\", { description: \"Couleur des points de niveau tracés sur les bougies.\" });\nconst TAILLE_POINTS = new Variable(\"number\", 1.6, { description: \"Taille des points de niveau. 1 donne un pointillé fin, 3 de gros points bien visibles.\", min: 0.5, max: 6 });\nconst NIVEAUX_MAX = new Variable(\"number\", 8, {\n  description:\n    \"Nombre maximum de niveaux tracés sur les bougies, les plus proches du cours d'abord. Le profil de droite continue de tous les montrer ; c'est seulement l'encombrement du graphe des prix (et de sa légende, une entrée par niveau) que ce plafond limite. Baisser PROM_THRESH en produit davantage, ce plafond décide de combien s'affichent.\",\n  min: 1,\n  max: 30,\n});\n// DEBOUNCE_MS est le seul nom que le moteur lit lui-même plutôt que de se contenter de le\n// substituer dans le code compilé (voir la doc de useScriptEngine) : il règle le délai d'anti-\n// rafale avant un recalcul déclenché par un tick de marché en direct qui ne fait que mettre à jour\n// la bougie encore en formation. Sans effet sur le replay ou l'arrivée d'une nouvelle bougie, qui\n// relancent toujours le script immédiatement, quelle que soit cette valeur.\nconst DEBOUNCE_MS = new Variable(\"number\", 0, {\n  description:\n    \"Délai (ms) avant de relancer le script suite à un tick de marché en direct sur la bougie déjà en formation. 0 = aucun anti-rafale, le script se relance à chaque tick.\",\n  min: 0,\n});\n\n// True Range moyen en espace log — une simple moyenne, pas le lissage de Wilder de ta.atr : ici\n// l'ATR ne sert qu'à donner un ordre de grandeur à la largeur de bande, et une moyenne franche est\n// plus facile à raisonner qu'une exponentielle qui traîne son propre historique.\nfunction meanLogATR(highs, lows, closes) {\n  if (closes.length < 2) return 0.0005;\n  let somme = 0;\n  for (let i = 1; i < closes.length; i++) {\n    const lh = Math.log(highs[i]);\n    const ll = Math.log(lows[i]);\n    const lpc = Math.log(closes[i - 1]);\n    somme += Math.max(lh - ll, Math.abs(lh - lpc), Math.abs(ll - lpc));\n  }\n  return somme / (closes.length - 1);\n}\n\n// Pics par proéminence : on part du sommet et on descend de chaque côté jusqu'à rencontrer un point\n// PLUS HAUT que lui — là, ce n'est plus sa vallée mais celle d'un pic voisin plus grand. La plus\n// haute des deux vallées ainsi trouvées donne la hauteur réelle du pic, ce qui distingue un vrai\n// sommet d'une simple bosse posée sur le flanc d'un autre.\nfunction findPeaks(values, minProminence) {\n  const peaks = [];\n  for (let i = 1; i < values.length - 1; i++) {\n    if (!(values[i] > values[i - 1] && values[i] > values[i + 1])) continue;\n    let leftMin = values[i];\n    for (let j = i - 1; j >= 0; j--) {\n      if (values[j] > values[i]) break;\n      if (values[j] < leftMin) leftMin = values[j];\n    }\n    let rightMin = values[i];\n    for (let j = i + 1; j < values.length; j++) {\n      if (values[j] > values[i]) break;\n      if (values[j] < rightMin) rightMin = values[j];\n    }\n    if (values[i] - Math.max(leftMin, rightMin) >= minProminence) peaks.push(i);\n  }\n  return peaks;\n}\n\n@block Cellule 2 — ne recalculer que tous les RECALC_EVERY bougies\nconst barIndex = state.get(\"barIndex\", 0);\nstate.set(\"barIndex\", barIndex + 1);\n\nif (barIndex >= WINDOW && barIndex % RECALC_EVERY === 0) {\n  const closes = market.series(\"close\", WINDOW);\n  const highs = market.series(\"high\", WINDOW);\n  const lows = market.series(\"low\", WINDOW);\n  const n = closes.length;\n  const logClose = closes.map(Math.log);\n\n  // Poids linéaires : la plus ancienne bougie pèse FIRST_W, la plus récente 1, puis on normalise\n  // pour que la somme fasse 1 — la densité obtenue est alors une vraie densité de probabilité,\n  // comparable d'une fenêtre à l'autre quelle que soit la valeur de WINDOW.\n  const poids = [];\n  for (let i = 0; i < n; i++) poids.push(Math.max(0, FIRST_W + (i * (1 - FIRST_W)) / n));\n  const totalPoids = poids.reduce((a, b) => a + b, 0);\n  const poidsNorm = poids.map((w) => w / totalPoids);\n\n  // Écart-type pondéré des log-clôtures : l'échelle naturelle des données. La largeur de bande en\n  // est un multiple, exactement comme scipy.gaussian_kde(bw_method=scalaire) pose h = scalaire ×\n  // std(données) — d'où une largeur qui s'adapte à la fois à la volatilité (par l'ATR) et à\n  // l'étalement de la fenêtre (par cet écart-type).\n  const moyennePond = logClose.reduce((s, x, i) => s + poids[i] * x, 0) / totalPoids;\n  const ecartPond = Math.sqrt(logClose.reduce((s, x, i) => s + poids[i] * (x - moyennePond) ** 2, 0) / totalPoids);\n  const h = meanLogATR(highs, lows, closes) * ATR_MULT * ecartPond;\n\n  if (h > 0) {\n    // La grille couvre exactement l'amplitude observée, sans marge : la densité aux deux bords est\n    // celle des clôtures extrêmes elles-mêmes, et le profil se lit sur la même plage que le prix.\n    const minV = Math.min(...logClose);\n    const maxV = Math.max(...logClose);\n    const step = (maxV - minV) / GRID;\n    const logGrid = [];\n    for (let v = minV; v <= maxV; v += step) logGrid.push(v);\n\n    // Somme des cloches, normalisée par 1 / (racine(2π) × h) — le facteur qui fait d'une somme de\n    // gaussiennes une densité dont l'intégrale vaut 1.\n    const norm = 1 / (Math.sqrt(2 * Math.PI) * h);\n    const density = logGrid.map((x) => {\n      let somme = 0;\n      for (let i = 0; i < n; i++) {\n        const u = (x - logClose[i]) / h;\n        somme += poidsNorm[i] * Math.exp(-0.5 * u * u);\n      }\n      return somme * norm;\n    });\n\n    // Retour en prix (exp) au tout dernier moment : le calcul entier s'est fait en log.\n    const priceGrid = logGrid.map(Math.exp);\n    const peakIdx = findPeaks(density, Math.max(...density) * PROM_THRESH);\n    state.set(\"levels\", peakIdx.map((i) => priceGrid[i]));\n    // Le profil complet est mémorisé lui aussi, pas seulement ses pics : c'est lui qu'on affiche.\n    state.set(\"density\", density);\n    state.set(\"priceGrid\", priceGrid);\n  }\n}\n\n@block Cellule 3 — afficher le profil, tourné, dans une pane ancrée à droite\n// pane.profile(nom, valeurs, prix) prend les deux tableaux d'un coup, comme plot.xy : un profil\n// n'est pas une série temporelle. Il est dessiné transposé — prix en vertical, densité en\n// horizontal — sur l'échelle de prix du graphe principal, donc chaque bosse est exactement à la\n// hauteur du prix qu'elle désigne.\n// headroom réserve un peu de largeur au-delà du pic le plus haut, pour que la courbe ne vienne\n// jamais coller à la barre de séparation. Ça ne peut pas se faire en divisant les densités avant\n// de les passer : l'échelle de la colonne va toujours de 0 au maximum du tableau reçu, donc son\n// maximum retombe sur le bord quel que soit le facteur appliqué — c'est l'échelle qu'il faut\n// élargir, pas les valeurs.\nconst profilDensite = state.get(\"density\", []);\nconst profilPrix = state.get(\"priceGrid\", []);\nplot.pane(\"Niveaux\", { dock: \"right\" }).profile(\"Densité\", profilDensite, profilPrix, {\n  color: PROFIL_COULEUR,\n  headroom: PROFIL_MARGE,\n});\n\n@block Cellule 4 — détecter un franchissement et signaler\n// Les niveaux (les pics du profil) sont relus ici : la cellule 3 dessine le profil, celle-ci\n// surveille les franchissements.\nconst levels = state.get(\"levels\", []);\nconst prevClose = market.close(1);\nconst currClose = market.close(0);\nif (prevClose !== null && currClose !== null) {\n  let sig = state.get(\"sig\", 0);\n  const prevSig = sig;\n  for (const level of levels) {\n    if (currClose > level && prevClose <= level) sig = 1;\n    else if (currClose < level && prevClose >= level) sig = -1;\n  }\n  if (sig !== prevSig && AFFICHER_FLECHES) {\n    plot.signal({ type: sig > 0 ? \"BUY\" : \"SELL\", price: currClose });\n  }\n  state.set(\"sig\", sig);\n}\n\n@block Cellule 5 — tracer les niveaux en points sur le graphique des prix\n// Le profil de droite montre OÙ sont les niveaux ; ces points les ramènent sur les bougies, à la\n// même hauteur que la bosse qui les a produits.\n//\n// .dots, et pas .line, pour une raison de fond : les niveaux sont recalculés à intervalle régulier\n// et rien ne garantit que le « niveau n° 3 » d'aujourd'hui soit le même objet que le « niveau n° 3 »\n// d'hier — un niveau peut apparaître, se décaler, disparaître, et tous ceux du dessus changent\n// alors de rang. Une ligne relierait ces valeurs entre elles et inventerait une continuité qui\n// n'existe pas ; des points ne relient rien, donc un changement de rang ne se voit tout simplement\n// pas. C'est exactement ce que fait le scatter de l'implémentation Python d'origine.\n//\n// .dots est aussi le seul tracé qui laisse de vrais trous : les autres prolongent leur dernière\n// valeur jusqu'au bord droit du graphe, celui-ci ne dessine rien tant que le script n'émet pas.\n// C'est ce qui permet à un segment de s'arrêter net quand son niveau cesse d'être détecté, au lieu\n// de filer à l'horizontale pour toujours. Appelé à chaque bougie (pas seulement sur la dernière),\n// il laisse donc derrière lui la trace de l'historique des niveaux.\nif (AFFICHER_NIVEAUX && currClose !== null) {\n  // Un profil bruité peut sortir trente pics ; les tracer tous couvrirait les bougies et donnerait\n  // trente entrées de légende. On garde les plus proches du cours — ceux contre lesquels le prix\n  // est effectivement en train de jouer — puis on les remet dans l'ordre des prix pour que les\n  // numéros de série se lisent de bas en haut.\n  const affiches = [...levels]\n    .sort((a, b) => Math.abs(a - currClose) - Math.abs(b - currClose))\n    .slice(0, NIVEAUX_MAX)\n    .sort((a, b) => a - b);\n\n  const niveaux = plot.overlay(\"Niveaux S/R\");\n  // Une couleur unique pour tous, comme la vidéo de référence : la couleur d'une série est fixée à\n  // son premier point, alors qu'un même niveau passe de résistance à support (et inversement) selon\n  // de quel côté du cours il se trouve — la teindre par rôle mentirait dès le premier croisement.\n  affiches.forEach((level, i) => {\n    niveaux.dots(\"Niveau \" + (i + 1), level, { color: COULEUR_NIVEAUX, lineWidth: TAILLE_POINTS });\n  });\n}\n```\n\n## Le même, en plusieurs fichiers et avec des classes\n```js\n@indicator\n@description \"///Niveaux S/R en plusieurs fichiers///\nExactement le même calcul que l'exemple précédent, mais **découpé en trois fichiers** et écrit avec\ndes classes plutôt qu'avec des fonctions et un sac de --state.get/set--.\n\n//Ce que fait chaque fichier//\n--noyau-- porte la KDE gaussienne (les poids, la largeur de bande, la grille de densité). --pics--\nporte la détection de pics par proéminence, sur un tableau de nombres quelconque. --niveaux--\nimporte les deux et les assemble en un objet **SuiviNiveaux** qui garde sa mémoire d'une bougie à\nl'autre. Le fichier principal ne fait plus que déclarer les réglages et afficher.\n\n//La règle à retenir//\nLe fichier principal est réexécuté **une fois par bougie** ; les autres fichiers sont évalués **une\nseule fois** par exécution. Une instance créée dans un fichier importé traverse donc tout\nl'historique, là où un --new-- écrit dans le fichier principal repartirait de zéro à chaque bougie —\nc'est pourquoi l'instance ci-dessous est rangée dans --state-- au premier passage.\n\"\n\n@block Cellule 1 — les réglages, et les trois fichiers qui font le travail\nimport { SuiviNiveaux } from \"./niveaux\";\n\nconst WINDOW = new Variable(\"number\", 500, {\n  description: \"Nombre de bougies passées prises en compte pour construire le profil.\",\n  min: 20,\n});\nconst GRID = new Variable(\"number\", 200, {\n  description: \"Nombre de paliers de prix sur lesquels la densité est évaluée. Plus haut = profil plus fin, mais plus lent.\",\n  min: 20,\n});\nconst FIRST_W = new Variable(\"number\", 0.01, {\n  description: \"Poids de la bougie la plus ancienne de la fenêtre par rapport à la plus récente (qui vaut 1).\",\n  min: 0,\n  max: 1,\n});\nconst ATR_MULT = new Variable(\"number\", 3, {\n  description: \"Largeur du noyau gaussien : ATR_MULT × ATR-log moyen × écart-type pondéré des log-clôtures.\",\n  min: 0.05,\n});\nconst PROM_THRESH = new Variable(\"number\", 0.25, {\n  description: \"Hauteur minimale qu'un pic doit dépasser au-dessus de ses vallées voisines, en fraction du pic le plus haut.\",\n  min: 0,\n  max: 1,\n});\nconst RECALC_EVERY = new Variable(\"number\", 5, {\n  description: \"Ne recalculer le profil qu'une bougie sur N. 1 = recalcul à chaque bougie.\",\n  min: 1,\n});\nconst PROFIL_COULEUR = new Variable(\"color\", \"#c47f2a\", { description: \"Couleur de la courbe du profil affichée dans la pane de droite.\" });\nconst AFFICHER_FLECHES = new Variable(\"boolean\", false, { description: \"Affiche les flèches BUY/SELL quand un niveau est franchi.\" });\nconst NIVEAUX_MAX = new Variable(\"number\", 8, { description: \"Nombre maximum de niveaux tracés sur les bougies.\", min: 1, max: 30 });\n\n// L'instance vit dans state parce que CE fichier-ci est rejoué à chaque bougie : un `new` écrit\n// directement ici reconstruirait un objet vide à chaque passage, et le suivi n'aurait aucune\n// mémoire. Les fichiers importés, eux, ne sont évalués qu'une fois — une instance créée là-bas\n// n'aurait pas eu besoin de ce détour.\nlet suivi = state.get(\"suivi\");\nif (!suivi) {\n  suivi = new SuiviNiveaux({\n    fenetre: WINDOW,\n    grille: GRID,\n    premierPoids: FIRST_W,\n    multiplicateurATR: ATR_MULT,\n    seuilProeminence: PROM_THRESH,\n    recalculTous: RECALC_EVERY,\n  });\n  state.set(\"suivi\", suivi);\n}\n\n@block Cellule 2 — une bougie de plus\nsuivi.observer(market);\n\n@block Cellule 3 — le profil, tourné, dans une pane ancrée à droite\nplot.pane(\"Niveaux\", { dock: \"right\" }).profile(\"Densité\", suivi.profil.densite, suivi.profil.prix, {\n  color: PROFIL_COULEUR,\n  headroom: 0.08,\n});\n\n@block Cellule 4 — franchissement et niveaux tracés sur les bougies\nconst courante = market.close(0);\nconst signal = suivi.franchissement(market.close(1), courante);\nif (signal && AFFICHER_FLECHES) plot.signal({ type: signal, price: courante });\n\nif (courante !== null) {\n  const niveaux = plot.overlay(\"Niveaux S/R\");\n  suivi.plusProches(courante, NIVEAUX_MAX).forEach((niveau, i) => {\n    niveaux.dots(\"Niveau \" + (i + 1), niveau, { color: PROFIL_COULEUR, lineWidth: 1.6 });\n  });\n}\n\n```\n\nFichier joint « noyau » :\n```js\n// Le calcul de densité, isolé du reste : ce fichier ne sait rien des paniques d'affichage, des\n// pics ni des franchissements — on lui donne des bougies, il rend un profil.\n//\n// Un fichier n'est évalué qu'UNE FOIS par exécution, pas une fois par bougie comme le fichier\n// principal. C'est ce qui rend une classe utile ici : l'instance construite au premier passage\n// traverse tout l'historique.\n\n/** True Range moyen en espace log — une simple moyenne, pas le lissage de Wilder de ta.atr : ici\n *  l'ATR ne sert qu'à donner un ordre de grandeur à la largeur de bande, et une moyenne franche est\n *  plus facile à raisonner qu'une exponentielle qui traîne son propre historique. */\nexport function moyenneATRLog(highs, lows, closes) {\n  if (closes.length < 2) return 0.0005;\n  let somme = 0;\n  for (let i = 1; i < closes.length; i++) {\n    const lh = Math.log(highs[i]);\n    const ll = Math.log(lows[i]);\n    const lpc = Math.log(closes[i - 1]);\n    somme += Math.max(lh - ll, Math.abs(lh - lpc), Math.abs(ll - lpc));\n  }\n  return somme / (closes.length - 1);\n}\n\n/** Une KDE gaussienne en espace log-prix, à la manière de scipy.gaussian_kde(bw_method=scalaire).\n *  Les réglages sont passés une fois au constructeur plutôt qu'à chaque appel : ils ne changent\n *  pas d'une bougie à l'autre, et les garder sur l'instance évite de les faire circuler. */\nexport class NoyauGaussien {\n  constructor({ premierPoids, multiplicateurATR, grille }) {\n    this.premierPoids = premierPoids;\n    this.multiplicateurATR = multiplicateurATR;\n    this.grille = grille;\n  }\n\n  /** Poids linéaires : la plus ancienne bougie pèse premierPoids, la plus récente 1. */\n  poids(n) {\n    const poids = [];\n    for (let i = 0; i < n; i++) poids.push(Math.max(0, this.premierPoids + (i * (1 - this.premierPoids)) / n));\n    return poids;\n  }\n\n  /** Le profil complet, ou null si la fenêtre ne permet pas de largeur de bande exploitable. */\n  profil(closes, highs, lows) {\n    const n = closes.length;\n    if (n === 0) return null;\n    const logClose = closes.map(Math.log);\n    const poids = this.poids(n);\n    const totalPoids = poids.reduce((a, b) => a + b, 0);\n    // Normalisés pour que la somme fasse 1 : la densité obtenue est alors une vraie densité de\n    // probabilité, comparable d'une fenêtre à l'autre quelle que soit la taille de la fenêtre.\n    const poidsNorm = poids.map((w) => w / totalPoids);\n\n    // Écart-type pondéré des log-clôtures : l'échelle naturelle des données. La largeur de bande en\n    // est un multiple, exactement comme scipy pose h = scalaire × std(données).\n    const moyennePond = logClose.reduce((s, x, i) => s + poids[i] * x, 0) / totalPoids;\n    const ecartPond = Math.sqrt(logClose.reduce((s, x, i) => s + poids[i] * (x - moyennePond) ** 2, 0) / totalPoids);\n    const h = moyenneATRLog(highs, lows, closes) * this.multiplicateurATR * ecartPond;\n    if (!(h > 0)) return null;\n\n    // La grille couvre exactement l'amplitude observée, sans marge : le profil se lit sur la même\n    // plage que le prix.\n    const minV = Math.min(...logClose);\n    const maxV = Math.max(...logClose);\n    const pas = (maxV - minV) / this.grille;\n    const logGrille = [];\n    for (let v = minV; v <= maxV; v += pas) logGrille.push(v);\n\n    // Somme des cloches, normalisée par 1 / (racine(2π) × h) — le facteur qui fait d'une somme de\n    // gaussiennes une densité dont l'intégrale vaut 1.\n    const norm = 1 / (Math.sqrt(2 * Math.PI) * h);\n    const densite = logGrille.map((x) => {\n      let somme = 0;\n      for (let i = 0; i < n; i++) {\n        const u = (x - logClose[i]) / h;\n        somme += poidsNorm[i] * Math.exp(-0.5 * u * u);\n      }\n      return somme * norm;\n    });\n\n    // Retour en prix (exp) au tout dernier moment : le calcul entier s'est fait en log.\n    return { prix: logGrille.map(Math.exp), densite };\n  }\n}\n\n```\n\nFichier joint « pics » :\n```js\n// La détection de pics, seule. Aucune notion de prix ici : ce fichier prend un tableau de nombres\n// et rend des indices — ce qui le rend testable et réutilisable pour n'importe quelle courbe.\n\n/** Pics par proéminence : on part du sommet et on descend de chaque côté jusqu'à rencontrer un\n *  point PLUS HAUT que lui — là, ce n'est plus sa vallée mais celle d'un pic voisin plus grand. La\n *  plus haute des deux vallées ainsi trouvées donne la hauteur réelle du pic, ce qui distingue un\n *  vrai sommet d'une simple bosse posée sur le flanc d'un autre. */\nexport class DetecteurPics {\n  /** @param seuil fraction du pic le plus haut qu'une bosse doit dépasser pour compter. */\n  constructor(seuil) {\n    this.seuil = seuil;\n  }\n\n  indices(valeurs) {\n    if (valeurs.length < 3) return [];\n    const minProeminence = Math.max(...valeurs) * this.seuil;\n    const pics = [];\n    for (let i = 1; i < valeurs.length - 1; i++) {\n      if (!(valeurs[i] > valeurs[i - 1] && valeurs[i] > valeurs[i + 1])) continue;\n      let creuxGauche = valeurs[i];\n      for (let j = i - 1; j >= 0; j--) {\n        if (valeurs[j] > valeurs[i]) break;\n        if (valeurs[j] < creuxGauche) creuxGauche = valeurs[j];\n      }\n      let creuxDroite = valeurs[i];\n      for (let j = i + 1; j < valeurs.length; j++) {\n        if (valeurs[j] > valeurs[i]) break;\n        if (valeurs[j] < creuxDroite) creuxDroite = valeurs[j];\n      }\n      if (valeurs[i] - Math.max(creuxGauche, creuxDroite) >= minProeminence) pics.push(i);\n    }\n    return pics;\n  }\n}\n\n```\n\nFichier joint « niveaux » :\n```js\n// Un fichier peut en importer un autre : celui-ci assemble le noyau et le détecteur de pics en un\n// seul objet qui garde sa mémoire d'une bougie à l'autre.\nimport { NoyauGaussien } from \"./noyau\";\nimport { DetecteurPics } from \"./pics\";\n\nexport class SuiviNiveaux {\n  constructor(options) {\n    this.noyau = new NoyauGaussien(options);\n    this.detecteur = new DetecteurPics(options.seuilProeminence);\n    this.fenetre = options.fenetre;\n    this.recalculTous = options.recalculTous;\n    this.compteur = 0;\n    this.niveaux = [];\n    this.profil = { prix: [], densite: [] };\n    this.signal = 0;\n  }\n\n  /** Appelé à chaque bougie. Ne recalcule qu'une fois sur recalculTous — entre deux recalculs, le\n   *  dernier profil obtenu est réutilisé tel quel, ce qui garde l'exécution sous le budget du\n   *  moteur sans rien changer à ce qui est affiché (les niveaux ne bougent pratiquement pas d'une\n   *  bougie à l'autre). */\n  observer(marche) {\n    const index = this.compteur++;\n    if (index < this.fenetre || index % this.recalculTous !== 0) return;\n    const profil = this.noyau.profil(\n      marche.series(\"close\", this.fenetre),\n      marche.series(\"high\", this.fenetre),\n      marche.series(\"low\", this.fenetre)\n    );\n    if (!profil) return;\n    this.profil = profil;\n    this.niveaux = this.detecteur.indices(profil.densite).map((i) => profil.prix[i]);\n  }\n\n  /** \"BUY\" / \"SELL\" au moment exact où le prix franchit un niveau, null le reste du temps. Le\n   *  signal précédent vit sur l'instance : c'est tout l'intérêt d'avoir un objet plutôt qu'une\n   *  fonction, il se souvient sans que l'appelant ait à lui repasser son propre état. */\n  franchissement(precedente, courante) {\n    if (precedente === null || courante === null) return null;\n    const avant = this.signal;\n    for (const niveau of this.niveaux) {\n      if (courante > niveau && precedente <= niveau) this.signal = 1;\n      else if (courante < niveau && precedente >= niveau) this.signal = -1;\n    }\n    if (this.signal === avant) return null;\n    return this.signal > 0 ? \"BUY\" : \"SELL\";\n  }\n\n  /** Les niveaux les plus proches du cours, remis dans l'ordre des prix — un profil bruité peut en\n   *  sortir trente, et les tracer tous couvrirait les bougies. */\n  plusProches(courante, maximum) {\n    return [...this.niveaux]\n      .sort((a, b) => Math.abs(a - courante) - Math.abs(b - courante))\n      .slice(0, maximum)\n      .sort((a, b) => a - b);\n  }\n}\n\n```\n\n## Stratégie — croisement MACD\n```js\n@strategy\n@description \"///Stratégie MACD///\nLong au passage de l'histogramme MACD au-dessus de zéro, short en dessous.\n\n//Ce que ça montre//\nLa mécanique complète d'une stratégie : le décorateur **@strategy**, les ordres\n--strategy.long()-- / --strategy.short()--, et le panneau de test qui s'ouvre sous la chart.\n\n//Ce que ça n'est pas//\nUne stratégie à trader. Un croisement de MACD nu perd de l'argent sur la plupart des marchés une\nfois les frais payés — c'est précisément ce que le facteur de profit du panneau vous dira.\n\"\n\n@block Réglages\n\nconst RAPIDE = new Variable(\"number\", 12, { description: \"Période de l'EMA rapide du MACD.\", min: 1, max: 200 });\nconst LENTE = new Variable(\"number\", 26, { description: \"Période de l'EMA lente du MACD.\", min: 1, max: 200 });\nconst SIGNAL = new Variable(\"number\", 9, { description: \"Période de la ligne de signal.\", min: 1, max: 200 });\n\n@block Le MACD, et son histogramme à la bougie précédente\n\nconst macd = ta.macd(market.series(\"close\", LENTE * 5), RAPIDE, LENTE, SIGNAL);\nconst histo = macd ? macd.histogram : null;\nconst histoAvant = state.get(\"histoAvant\", null);\nstate.set(\"histoAvant\", histo);\n\n@block Les règles d'entrée\n\n// Un croisement, pas un état : on compare à la bougie précédente. Sans ce test, la condition\n// \"histogramme positif\" serait vraie sur toute une tendance et déclencherait une entrée par\n// bougie, que le pyramiding se contenterait ensuite d'ignorer en silence.\nif (histo !== null && histoAvant !== null) {\n  if (histoAvant <= 0 && histo > 0) strategy.long(\"MACD haussier\");\n  if (histoAvant >= 0 && histo < 0) strategy.short(\"MACD baissier\");\n}\n\n@block Le MACD lui-même, pour pouvoir lire la stratégie\n\n// Une stratégie reste un script : elle peut tracer ce qu'elle veut. Voir l'histogramme sous les\n// bougies est ce qui permet de comprendre *pourquoi* un trade s'est déclenché là.\nif (macd && macd.macd !== null && macd.signal !== null) {\n  const pane = plot.pane(\"MACD\");\n  pane.line(\"MACD\", macd.macd, { color: \"#6c87c9\" });\n  pane.line(\"Signal\", macd.signal, { color: \"#e0a95c\" });\n  pane.histogram(\"Histogramme\", macd.histogram ?? 0, { color: \"#7fb37f\" });\n}\n```\n\n## Stratégie — croisement de moyennes\n```js\n@strategy\n@description \"///Croisement de moyennes///\nLong quand la moyenne courte croise la longue à la hausse, sortie au croisement inverse.\n\n//À quoi ça sert//\nC'est la stratégie de référence : celle à laquelle comparer les autres. Si une règle compliquée ne\nbat pas celle-ci sur le même instrument, elle ne vaut pas sa complexité.\n\n//Ce qu'il faut regarder dans le panneau//\nLe **facteur de profit** (au-dessus de 1, elle gagne), le **drawdown max** (ce qu'il a fallu\nencaisser pour l'obtenir), et la part des **commissions** dans le profit brut.\n\"\n\n@block Réglages\n\nconst COURTE = new Variable(\"number\", 20, { description: \"Période de la moyenne courte.\", min: 2, max: 200 });\nconst LONGUE = new Variable(\"number\", 50, { description: \"Période de la moyenne longue.\", min: 3, max: 400 });\n\n@block Les deux moyennes, et leur position à la bougie précédente\n\nconst courte = math.sma(market.series(\"close\", COURTE), COURTE);\nconst longue = math.sma(market.series(\"close\", LONGUE), LONGUE);\n\n// Un croisement se détecte par un CHANGEMENT de position relative, pas par la position elle-même.\n// Sans cette mémoire, \"courte au-dessus de longue\" resterait vrai pendant toute une tendance et on\n// tenterait une entrée à chaque bougie — que le pyramiding se contenterait d'ignorer en silence.\nconst auDessusAvant = state.get(\"auDessus\", null);\nconst auDessus = courte !== null && longue !== null ? courte > longue : null;\nstate.set(\"auDessus\", auDessus);\n\n@block Les règles\n\nif (auDessus !== null && auDessusAvant !== null && auDessus !== auDessusAvant) {\n  if (auDessus) strategy.long(\"Croisement haussier\");\n  else strategy.close(\"Croisement baissier\");\n}\n\n@block Les moyennes sur la chart, pour pouvoir lire les trades\n\n// Une stratégie reste un script : voir les deux courbes est ce qui permet de comprendre pourquoi\n// un trade s'est déclenché à cet endroit-là plutôt qu'un autre.\nconst overlay = plot.overlay(\"Croisement de moyennes\");\nif (courte !== null) overlay.line(\"SMA \" + COURTE, courte, { color: \"#e0a95c\" });\nif (longue !== null) overlay.line(\"SMA \" + LONGUE, longue, { color: \"#6c87c9\" });\n```";
